/* CSIR NET Life Sciences, December 2024 (exam of 1 March 2025, shift 1): 145 questions with NTA's final answer key.
 * Loaded on demand by index.html when a candidate opens the paper.
 * Each question: id (1-145), part (A/B/C), unit (syllabus unit 1-14, null for Part A), blocks (text / image / table),
 * options (keys 1-4), answer (the key of the correct option) and explanation ({correct, wrong, notes}).
 * Where NTA's final key accepts more than one option, `accept` lists every accepted key (answer is the first of them). */
window.PYQ_PAPERS = window.PYQ_PAPERS || {};
window.PYQ_PAPERS['pyq-dec2024'] = [{"id":1,"part":"A","unit":null,"blocks":[{"t":"p","h":"Masses of several objects were measured on the Earth as well as on the Moon using the same two-pan balance. The graph of the measurements obtained on the two sites would appear as"},{"t":"img","src":"data:image/webp;base64,","w":415,"h":360,"alt":"Four graphs of measurement on Moon against measurement on Earth: (1) a shallow line reaching about 1.7 at 10, (2) a steep line reaching 10 at about 1.7, (3) a straight line through the origin with slope 1, (4) a flat line at 5"}],"options":[{"key":"1","text":"Graph 1"},{"key":"2","text":"Graph 2"},{"key":"3","text":"Graph 3"},{"key":"4","text":"Graph 4"}],"answer":"3","explanation":{"correct":"A two-pan balance compares the unknown mass with standard masses. Gravity acts equally on both pans, so the value of <i>g</i> cancels out and the balance reads <b>mass</b>, not weight. The same object therefore reads the same on the Earth and on the Moon, giving a straight line through the origin with slope 1 (Graph 3).","wrong":{"1":"Slope ≈ 1/6 is what a <i>spring</i> balance (which measures weight, <i>mg</i>) would show, since lunar <i>g</i> ≈ 1/6 of Earth's.","2":"Slope ≈ 6 would mean the Moon reading is six times larger, the reverse of even the weight relationship.","4":"A constant reading of 5 for every object would mean the balance does not respond to mass at all."}}},{"id":2,"part":"A","unit":null,"blocks":[{"t":"p","h":"In the fictional country of Petreversia, which of the following provinces is the odd one out?"}],"options":[{"key":"1","text":"TANGODIN"},{"key":"2","text":"PATACAHON"},{"key":"3","text":"BACCANEH"},{"key":"4","text":"HORVITHA"}],"answer":"4","explanation":{"correct":"The country's name hints at the trick: \"<b>Pet re-versia</b>\", i.e. read the names in reverse to find pets/animals. TANGODIN → NIDO<b>GNAT</b> (contains DOG and GNAT); PATACAHON → NOHA<b>CAT</b>AP (CAT); BACCANEH → <b>HEN</b>ACCAB (HEN). HORVITHA → AHTIVROH hides no animal, so it is the odd one out.","wrong":{"1":"Reversed it reads NIDOGNAT, which contains DOG and GNAT.","2":"Reversed it reads NOHACATAP, which contains CAT.","3":"Reversed it reads HENACCAB, which contains HEN."}}},{"id":3,"part":"A","unit":null,"blocks":[{"t":"p","h":"A boy in a family says \"I have twice as many sisters as I have brothers\" but one of his sisters claims that she has the same number of brothers and sisters. The numbers of girls and boys in that family are, respectively"}],"options":[{"key":"1","text":"4 and 2"},{"key":"2","text":"3 and 2"},{"key":"3","text":"3 and 4"},{"key":"4","text":"4 and 3"}],"answer":"4","explanation":{"correct":"Let there be <i>g</i> girls and <i>b</i> boys. The boy: <i>g</i> = 2(<i>b</i> − 1). The sister: <i>g</i> − 1 = <i>b</i>. Substituting, <i>b</i> + 1 = 2<i>b</i> − 2, so <i>b</i> = 3 and <i>g</i> = 4. Check: the boy has 4 sisters and 2 brothers; a girl has 3 sisters and 3 brothers.","wrong":{"1":"With 4 girls and 2 boys, a boy has 4 sisters and 1 brother (4×, not 2×).","2":"With 3 girls and 2 boys, a girl has 2 sisters and 2 brothers (fine), but a boy has 3 sisters and 1 brother (3×).","3":"With 3 girls and 4 boys, a boy has fewer sisters than brothers."}}},{"id":4,"part":"A","unit":null,"blocks":[{"t":"p","h":"The geometric mean of squares of two positive integers is 10. The smallest possible sum of these two integers is"}],"options":[{"key":"1","text":"7"},{"key":"2","text":"8"},{"key":"3","text":"11"},{"key":"4","text":"10"}],"answer":"1","explanation":{"correct":"√(<i>a</i>²·<i>b</i>²) = <i>ab</i> = 10. Positive-integer pairs with product 10 are (1, 10) and (2, 5). Their sums are 11 and 7, so the smallest possible sum is 7.","wrong":{"2":"No pair of positive integers with product 10 sums to 8.","3":"11 is the sum for (1, 10), which is possible but not the smallest.","4":"No pair of positive integers with product 10 sums to 10."}}},{"id":5,"part":"A","unit":null,"blocks":[{"t":"p","h":"The given figure shows a line fit using least squares method between profit in chocolate business and mean temperature (T) data for a city. The correlation coefficient obtained from this data is <i>r</i>. Which one of the following statements is INCORRECT?"},{"t":"img","src":"data:image/webp;base64,","w":560,"h":420,"alt":"Scatter plot of profit (million rupees) against mean temperature 22 to 38 °C with a fitted line Profit = 4T − 86, r = 0.83; one point at (32, 80) lies well above the line"}],"options":[{"key":"1","text":"The sum of the squared differences between the observed and estimated values of profit is minimum."},{"key":"2","text":"About 69% of the variation in profit is explained by the variation in temperature."},{"key":"3","text":"At 30°C, estimated profit is 34 million ₹."},{"key":"4","text":"Data point (32, 80) is anomalous and therefore must be discarded."}],"answer":"4","explanation":{"correct":"A point that lies far from the fitted line is an <i>outlier</i>, but being far from the line is not by itself a reason to delete it. A point is removed only with an independent justification (measurement error, a different population); otherwise discarding it is data manipulation. The statement is therefore incorrect.","wrong":{"1":"Correct: this is the definition of an ordinary least-squares fit, which minimises Σ(<i>y</i> − ŷ)².","2":"Correct: the coefficient of determination is <i>r</i>² = 0.83² ≈ 0.69, i.e. ~69% of the variance in profit is explained by temperature.","3":"Correct: 4 × 30 − 86 = 34 million ₹."}}},{"id":6,"part":"A","unit":null,"blocks":[{"t":"p","h":"A cube is coloured on each face by one of yellow, orange, red, blue, green and pink colours. Orange is opposite to yellow. Pink is between orange and yellow. Red is alongside of Pink. Green is between red and blue. Orange is at top. What is opposite to blue?"}],"options":[{"key":"1","text":"Red"},{"key":"2","text":"Green"},{"key":"3","text":"Pink"},{"key":"4","text":"Yellow"}],"answer":"1","explanation":{"correct":"Orange is on top, so yellow is at the bottom. The other four colours form the ring of side faces. Pink is a side face; red is next to pink; green lies between red and blue, so going round the ring the order is pink → red → green → blue. In a ring of four faces, alternate faces are opposite: pink is opposite green, and <b>red is opposite blue</b>.","wrong":{"2":"Green is adjacent to blue (it lies between red and blue).","3":"Pink is adjacent to blue (the ring closes from blue back to pink).","4":"Yellow is the bottom face, opposite orange."}}},{"id":7,"part":"A","unit":null,"blocks":[{"t":"p","h":"How many 4-digit numbers can be generated from the digits 1, 2, 3, 4, 5 and 6 such that 123 always appear as a string? No digit appears more than once."}],"options":[{"key":"1","text":"8"},{"key":"2","text":"4"},{"key":"3","text":"6"},{"key":"4","text":"12"}],"answer":"3","explanation":{"correct":"Treat \"123\" as one block. The fourth digit must be one of 4, 5 or 6 (3 choices), and it can go before or after the block (2 positions): 3 × 2 = 6 numbers (1234, 1235, 1236, 4123, 5123, 6123).","wrong":{"1":"8 would need 4 choices for the extra digit; only 4, 5 and 6 remain.","2":"4 ignores either one of the positions or one of the free digits.","4":"12 double-counts: the block's internal order is fixed as 1-2-3."}}},{"id":8,"part":"A","unit":null,"blocks":[{"t":"p","h":"An item in a shop is priced at ₹375 excluding tax. The shopkeeper offers a discount of 15%, however there is a tax of 12% before discount on the item. The selling price of the item is:"}],"options":[{"key":"1","text":"₹318.75"},{"key":"2","text":"₹420"},{"key":"3","text":"₹357"},{"key":"4","text":"₹382.5"}],"answer":"3","explanation":{"correct":"Tax is applied first: 375 × 1.12 = ₹420. The 15% discount is then applied to this taxed price: 420 × 0.85 = ₹357. (Because both are multiplicative, 375 × 1.12 × 0.85 gives the same ₹357 in either order.)","wrong":{"1":"₹318.75 = 375 × 0.85 applies the discount but ignores the tax.","2":"₹420 includes the tax but ignores the discount.","4":"₹382.5 would be 375 × 1.02, i.e. a net +2% (adding the percentages instead of multiplying factors)."}}},{"id":9,"part":"A","unit":null,"blocks":[{"t":"p","h":"Five girls are standing in a line. Out of them, Henna is to the left of Agatha, between Agatha and Dipti there are 3 places, and Shabnam has both Lata and Dipti as neighbours. Then,"}],"options":[{"key":"1","text":"Lata is to the right of Agatha"},{"key":"2","text":"Henna is at the extreme Left"},{"key":"3","text":"there are exactly two places between Henna &amp; Dipti"},{"key":"4","text":"there is exactly one place between Shabnam &amp; Agatha"}],"answer":"3","explanation":{"correct":"With five places, three places between Agatha and Dipti puts them at the two ends (positions 1 and 5). Henna is to the left of Agatha, so Agatha is at 5 and Dipti at 1. Shabnam has Dipti and Lata as neighbours, so Shabnam is 2 and Lata is 3, leaving Henna at 4. Line: Dipti, Shabnam, Lata, Henna, Agatha. Between Henna (4) and Dipti (1) are positions 2 and 3: exactly two places.","wrong":{"1":"Lata (3) is to the left of Agatha (5).","2":"Dipti is at the extreme left; Henna is fourth.","4":"Between Shabnam (2) and Agatha (5) are two places, not one."}}},{"id":10,"part":"A","unit":null,"blocks":[{"t":"p","h":"A 6-digit security code is made using digits from 0 to 9. The first and the last digits are known. If the remaining four digits are known to be primes, at the most how many trials are required to determine the code?"}],"options":[{"key":"1","text":"100"},{"key":"2","text":"2560"},{"key":"3","text":"256"},{"key":"4","text":"10000"}],"answer":"3","explanation":{"correct":"The single-digit primes are 2, 3, 5 and 7 (4 choices). Each of the four unknown positions can take any of them (repetition allowed), so the worst case is 4<sup>4</sup> = 256 trials.","wrong":{"1":"100 does not correspond to any count of 4 positions × 4 primes.","2":"2560 multiplies 256 by an extra factor of 10 for a digit that is already known.","4":"10<sup>4</sup> = 10000 ignores the information that the digits are prime."}}},{"id":11,"part":"A","unit":null,"blocks":[{"t":"p","h":"A fair coin is tossed two times independently and X denotes the number of heads. Then a fair 6-faced die is thrown at random (independently of the tosses) and Y denotes the number on the top of the die. What is the probability that the value of X + Y is 4?"}],"options":[{"key":"1","text":"1/2"},{"key":"2","text":"1/3"},{"key":"3","text":"1/4"},{"key":"4","text":"1/6"}],"answer":"4","explanation":{"correct":"P(X = 0, 1, 2) = 1/4, 1/2, 1/4. For X + Y = 4 we need Y = 4, 3 or 2 respectively, each with probability 1/6. P = (1/4 + 1/2 + 1/4) × 1/6 = 1/6. Intuitively: whatever X turns out to be (0–2), exactly one face of the die completes the sum to 4.","wrong":{"1":"1/2 is P(X = 1) alone.","2":"1/3 has no basis in the joint distribution.","3":"1/4 is P(X = 0) or P(X = 2), not the joint probability."}}},{"id":12,"part":"A","unit":null,"blocks":[{"t":"p","h":"If the words FAST, SLOW and TONE are written as 3475, 2913 and 1648 but not necessarily in the same order, then using the same code how the word NEAT would be written?"}],"options":[{"key":"1","text":"7513"},{"key":"2","text":"7953"},{"key":"3","text":"7593"},{"key":"4","text":"1537"}],"answer":"3","explanation":{"correct":"Shared letters fix the pairing by position. FAST and SLOW share S (3rd letter of FAST, 1st of SLOW); FAST and TONE share T (4th of FAST, 1st of TONE). In 2913 the 3rd digit (1) begins 1648 and the 4th digit (3) begins 3475, so FAST = 2913, SLOW = 1648 and TONE = 3475. This gives F=2, A=9, S=1, T=3, L=6, O=4, W=8, N=7, E=5 (O = 4 is consistent in SLOW and TONE). NEAT = 7-5-9-3 = 7593.","wrong":{"1":"7513 uses S's code (1) for A.","2":"7953 swaps the codes of E and A.","4":"1537 starts with S's code."}}},{"id":13,"part":"A","unit":null,"blocks":[{"t":"p","h":"Let A: export, B: rainfall, C: harvest, D: godown storage. Which one of the following sequences is correct?"}],"options":[{"key":"1","text":"C, A, B, D"},{"key":"2","text":"B, C, D, A"},{"key":"3","text":"C, B, A, D"},{"key":"4","text":"D, C, B, A"}],"answer":"2","explanation":{"correct":"The logical agricultural chain is rainfall (B) → crop and harvest (C) → storage in godowns (D) → export (A).","wrong":{"1":"Harvest cannot precede the rainfall that raises the crop, and export cannot precede storage.","3":"Rainfall after harvest breaks the cause-effect order.","4":"This is the exact reverse of the chain."}}},{"id":14,"part":"A","unit":null,"blocks":[{"t":"p","h":"Fifteen distinct points are randomly placed on the circumference of a circle. At most how many triangles can be formed using these points?"}],"options":[{"key":"1","text":"105"},{"key":"2","text":"455"},{"key":"3","text":"2730"},{"key":"4","text":"30"}],"answer":"2","explanation":{"correct":"No three points on a circle are collinear, so every choice of 3 points gives a triangle: <sup>15</sup>C<sub>3</sub> = (15 × 14 × 13)/6 = 455.","wrong":{"1":"105 = <sup>15</sup>C<sub>2</sub>, the number of chords (pairs), not triangles.","3":"2730 = 15 × 14 × 13 counts ordered triples (each triangle 6 times).","4":"30 has no combinatorial basis here."}}},{"id":15,"part":"A","unit":null,"blocks":[{"t":"p","h":"√(0.99 × 0.99 × 0.99) is closest to"}],"options":[{"key":"1","text":"0.99 × 0.33"},{"key":"2","text":"0.33 × 0.33 × 0.33"},{"key":"3","text":"0.99 × 0.99 × 0.99"},{"key":"4","text":"0.33"}],"answer":"3","explanation":{"correct":"√(0.99³) = 0.99<sup>1.5</sup> ≈ 0.985. The candidates are 0.327, 0.036, 0.970 and 0.33. The closest is 0.99³ ≈ 0.970 (difference ≈ 0.015).","wrong":{"1":"0.99 × 0.33 ≈ 0.327, far below 0.985.","2":"0.33³ ≈ 0.036.","4":"0.33 is far below 0.985."}}},{"id":16,"part":"A","unit":null,"blocks":[{"t":"p","h":"The sum of the digits of a four-digit number 'abcd' is subtracted from the number. Then the result of this will be always divisible by"}],"options":[{"key":"1","text":"9"},{"key":"2","text":"11"},{"key":"3","text":"13"},{"key":"4","text":"14"}],"answer":"1","explanation":{"correct":"(1000a + 100b + 10c + d) − (a + b + c + d) = 999a + 99b + 9c = 9(111a + 11b + c), which is always a multiple of 9.","wrong":{"2":"Only the 99b term is a multiple of 11; 999a and 9c are not in general.","3":"Not a factor of the general expression.","4":"Not a factor of the general expression."}}},{"id":17,"part":"A","unit":null,"blocks":[{"t":"p","h":"If you add liquid soap in the centre of a bowl of water, which has black pepper flakes floating in it, the pepper flakes will"}],"options":[{"key":"1","text":"start dissolving"},{"key":"2","text":"move away from the centre"},{"key":"3","text":"settle down"},{"key":"4","text":"not move"}],"answer":"2","explanation":{"correct":"Soap is a surfactant that lowers the surface tension where it is added. The higher surface tension of the clean water further out pulls the surface (and the floating flakes) outward, away from the centre. This flow driven by a surface-tension gradient is the <b>Marangoni effect</b>.","wrong":{"1":"Pepper is hydrophobic and insoluble in water.","3":"The flakes may eventually wet and sink, but the immediate, characteristic response is outward motion.","4":"The surface-tension gradient produces visible motion at once."}}},{"id":18,"part":"A","unit":null,"blocks":[{"t":"p","h":"A cylinder has two concentric identical metal plates placed on each other that have identical circular holes as shown in the figure (shaded area). The plate A rotates in clockwise direction at 15° per second. The plate B rotates in anti-clockwise direction at 5° per second. If the starting positions of the plates as seen from the top of the cylinder are as shown below, the first instance when both the shaded regions completely coincide happens at:"},{"t":"img","src":"data:image/webp;base64,","w":720,"h":230,"alt":"Plate A with its hole at the 12 o'clock position, rotating clockwise at 15 degrees per second; plate B with its hole on the lower-left diagonal (225 degrees clockwise from 12 o'clock), rotating anticlockwise at 5 degrees per second; plates stacked in a cylinder"}],"options":[{"key":"1","text":"11.25 seconds"},{"key":"2","text":"3.25 seconds"},{"key":"3","text":"6.75 seconds"},{"key":"4","text":"8.35 seconds"}],"answer":"1","explanation":{"correct":"Hole A starts at 12 o'clock; hole B sits on the lower-left diagonal, i.e. 225° clockwise from 12 o'clock. A moves clockwise and B anticlockwise, so they close the 225° gap at a combined 15 + 5 = 20° per second: 225 / 20 = 11.25 s. (Check: A has turned 168.75° clockwise and B 56.25° anticlockwise, both reaching 168.75° from 12 o'clock.)","wrong":{"2":"3.25 s × 20°/s = 65°, which matches no gap in the figure.","3":"6.75 s × 20°/s = 135°, which is the anticlockwise gap; but A moves clockwise, so the holes close the 225° clockwise gap.","4":"8.35 s × 20°/s = 167°, which matches no gap in the figure."}}},{"id":19,"part":"A","unit":null,"blocks":[{"t":"p","h":"A rectangular sheet of 31.4 cm × 10 cm size is rolled across its length to make a cylinder without overlap. What will be the approximate volume of the cylinder?"}],"options":[{"key":"1","text":"785 cm<sup>3</sup>"},{"key":"2","text":"1570 cm<sup>3</sup>"},{"key":"3","text":"3140 cm<sup>3</sup>"},{"key":"4","text":"6280 cm<sup>3</sup>"}],"answer":"1","explanation":{"correct":"Rolled across its length, the 31.4 cm side becomes the circumference: 2πr = 31.4, so r = 5 cm and the height is 10 cm. V = πr²h = 3.14 × 25 × 10 ≈ 785 cm³.","wrong":{"2":"1570 cm³ is double the correct value.","3":"3140 cm³ would need r = 10 cm.","4":"6280 cm³ has no consistent geometry here."}}},{"id":20,"part":"A","unit":null,"blocks":[{"t":"p","h":"Choose the option to fill in the blank that will make the following statement logically correct"},{"t":"p","h":"COUNTING WITH PRECISION THE NUMBER OF OCCURRENCES OF THE LETTER \"I\" IN THIS SENTENCE YIELDS ____"}],"options":[{"key":"1","text":"SEVEN"},{"key":"2","text":"EIGHT"},{"key":"3","text":"NINE"},{"key":"4","text":"TEN"}],"answer":"3","explanation":{"correct":"Without the blank, the letter I occurs in COUNTING (1), WITH (1), PRECISION (2), \"I\" (1), IN (1), THIS (1) and YIELDS (1): 8 times. The answer word must make the total equal to itself: NINE contains one more I, giving 8 + 1 = 9. It is the only self-consistent choice.","wrong":{"1":"SEVEN adds no I, so the count would be 8, not 7.","2":"EIGHT adds one I, making the count 9, not 8.","4":"TEN adds no I, so the count would be 8, not 10."}}},{"id":21,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following is the most significant factor that explains the evolution of iteroparity in animals?"}],"options":[{"key":"1","text":"Slower developmental rates over their lifespan"},{"key":"2","text":"Predictable environmental conditions"},{"key":"3","text":"Low adult survival rates"},{"key":"4","text":"Cost per reproductive event is high"}],"answer":"2","explanation":{"correct":"Iteroparity (repeated breeding) is favoured where adults can expect to survive to breed again and where the environment is stable and predictable, so that reserving resources for future bouts pays off. This is the classic association of iteroparity with stable, density-regulated (K-type) environments, as opposed to semelparity in unpredictable or high-adult-mortality settings (Cole 1954; Charnov &amp; Schaffer 1973; Stearns 1992).","wrong":{"1":"Developmental rate influences age at maturity, not the choice between one and many breeding bouts.","3":"Low adult survival favours <i>semelparity</i>: if an adult is unlikely to survive, it should invest everything in one bout.","4":"A high fixed cost per breeding event also favours semelparity (one large bout amortises the cost)."}}},{"id":22,"part":"B","unit":8,"blocks":[{"t":"p","h":"In a population with the ABO blood group system, if the frequency of the allele I<sup>A</sup> is 0.3, the frequency of the allele I<sup>B</sup> is 0.2, and the frequency of the allele i is 0.5, what would be the expected percentage of population with blood group A, considering that the population is under Hardy-Weinberg equilibrium?"}],"options":[{"key":"1","text":"9%"},{"key":"2","text":"24%"},{"key":"3","text":"39%"},{"key":"4","text":"42%"}],"answer":"3","explanation":{"correct":"Blood group A comprises I<sup>A</sup>I<sup>A</sup> and I<sup>A</sup>i. Under Hardy–Weinberg: p² + 2pr = 0.3² + 2(0.3)(0.5) = 0.09 + 0.30 = 0.39, i.e. 39%.","wrong":{"1":"9% is only the I<sup>A</sup>I<sup>A</sup> homozygotes (p²).","2":"24% does not correspond to any ABO class here (blood group B would be q² + 2qr = 0.04 + 0.20 = 24%).","4":"42% has no basis in these frequencies."}}},{"id":23,"part":"B","unit":5,"blocks":[{"t":"p","h":"Hormone pregnancy tests work by detecting the presence of the hormone, human chorionic gonadotropin (hCG) using immunoassay. Which types of cells will develop to produce hCG in pregnant females?"}],"options":[{"key":"1","text":"Pluripotent stem cells"},{"key":"2","text":"Trophoblast cells"},{"key":"3","text":"Endometrial cells"},{"key":"4","text":"Granulosa cells"}],"answer":"2","explanation":{"correct":"hCG is secreted by the trophoblast, chiefly the syncytiotrophoblast that forms from the outer cell layer of the blastocyst during implantation. It maintains the corpus luteum (an LH-like action) until the placenta takes over progesterone production.","wrong":{"1":"The inner cell mass (pluripotent) forms the embryo proper and does not secrete hCG.","3":"The endometrium is maternal tissue that becomes the decidua; it does not make hCG.","4":"Granulosa cells are ovarian follicle cells that make oestrogen and inhibin."}}},{"id":24,"part":"B","unit":3,"blocks":[{"t":"p","h":"Match the columns:"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X: <i>E. coli</i> genes involved in replication","Column Y: Functional eukaryotic orthologues"]],"rows":[["A. DnaB","i. Pol α/primase"],["B. DnaC","ii. Cdc6"],["C. β clamp","iii. PCNA"],["D. DnaG","iv. MCM complex"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A (i) B (ii) C (iii) D (iv)"},{"key":"2","text":"A (iv) B (i) C (ii) D (iii)"},{"key":"3","text":"A (iv) B (ii) C (iii) D (i)"},{"key":"4","text":"A (ii) B (iv) C (iii) D (i)"}],"answer":"3","explanation":{"correct":"DnaB is the replicative helicase, the functional counterpart of the MCM2–7 complex (iv). DnaC loads DnaB onto DNA, as Cdc6 (with Cdt1) loads MCM (ii). The β sliding clamp corresponds to PCNA (iii). DnaG is the primase, the counterpart of Pol α/primase (i).","wrong":{"1":"Makes DnaB a primase and DnaG a helicase.","2":"Mismatches all four pairs.","4":"Swaps the helicase (MCM) and its loader (Cdc6)."}}},{"id":25,"part":"B","unit":5,"blocks":[{"t":"p","h":"The regeneration of a severed Axolotl limb is mediated by which one of the following cellular responses to injury?"}],"options":[{"key":"1","text":"Blastema formation"},{"key":"2","text":"Transdifferentiation"},{"key":"3","text":"Induced pluripotency"},{"key":"4","text":"Stem cell dedifferentiation"}],"answer":"1","explanation":{"correct":"After amputation, the wound epidermis forms an apical epithelial cap and underlying cells accumulate as a <b>blastema</b>, a mass of lineage-restricted progenitors that proliferates and re-patterns the missing limb (epimorphic regeneration). Lineage tracing shows blastema cells largely keep their tissue memory rather than becoming pluripotent (Kragl et al. 2009, <i>Nature</i> 460:60–65).","wrong":{"2":"Transdifferentiation (e.g. lens regeneration from the dorsal iris in newts) is not the main mechanism of limb regeneration.","3":"Blastema cells do not revert to pluripotency.","4":"Dedifferentiation contributes cells to the blastema, but the organising response named for limb regeneration is blastema formation."}}},{"id":26,"part":"B","unit":2,"blocks":[{"t":"p","h":"A transmembrane receptor protein (X) and a transmembrane protein bound to the actin cytoskeleton (Y) with fluorescent tags were expressed in a cell. A fluorescence recovery after photobleaching (FRAP) experiment was performed on these proteins. Which one of the following options represents the most likely outcome of this experiment?"}],"options":[{"key":"1","text":"Fluorescence of both proteins will be recovered at the same rate."},{"key":"2","text":"Fluorescence of X will be recovered later than Y."},{"key":"3","text":"Fluorescence of Y will be recovered later than X."},{"key":"4","text":"Being membrane proteins, no recovery of fluorescence is expected."}],"answer":"3","explanation":{"correct":"FRAP recovery depends on lateral diffusion of unbleached molecules into the bleached area. A freely diffusing receptor (X) recovers quickly, whereas a protein tethered to the cortical actin cytoskeleton (Y) has restricted mobility and a larger immobile fraction, so it recovers more slowly and less completely.","wrong":{"1":"Cytoskeletal tethering clearly reduces mobility, so the rates differ.","2":"This reverses the expected order.","4":"Membrane proteins do diffuse laterally (fluid-mosaic model), so recovery occurs."}}},{"id":27,"part":"B","unit":2,"blocks":[{"t":"p","h":"Dynein is a microtubule-dependent motor protein essential for cellular processes. Which one of the following statements related to dynein function is INCORRECT?"}],"options":[{"key":"1","text":"It helps in cilia and flagella beating."},{"key":"2","text":"It transports organelles in anterograde direction."},{"key":"3","text":"It participates in spindle assembly and positioning."},{"key":"4","text":"It interacts with dynactin for efficient transport."}],"answer":"2","explanation":{"correct":"Cytoplasmic dynein is a minus-end-directed motor. In axons it carries cargo <b>retrogradely</b> (towards the cell body); anterograde (plus-end) transport is done by most kinesins.","wrong":{"1":"Correct: axonemal dyneins slide outer doublets to bend cilia and flagella.","3":"Correct: dynein focuses spindle poles and pulls on astral microtubules from the cortex.","4":"Correct: dynactin (with an adaptor such as BICD2) activates dynein and increases its processivity."}}},{"id":28,"part":"B","unit":14,"blocks":[{"t":"p","h":"Which of the following molecular marker techniques uses a single primer in a PCR reaction for identifying polymorphisms between genotypes?"}],"options":[{"key":"1","text":"SSR (Simple sequence repeats)"},{"key":"2","text":"AFLP (Amplified fragment length polymorphism)"},{"key":"3","text":"RAPD (Randomly amplified polymorphic DNA)"},{"key":"4","text":"SCAR (Sequence characterized amplified regions)"}],"answer":"3","explanation":{"correct":"RAPD uses a single short (~10-mer) arbitrary primer at low annealing stringency; fragments arise wherever the primer binds on both strands within amplifiable distance (Williams et al. 1990, <i>Nucleic Acids Res</i> 18:6531).","wrong":{"1":"SSR markers use a pair of locus-specific primers flanking the repeat.","2":"AFLP uses adaptor-specific primer pairs after restriction-ligation.","4":"SCARs are locus-specific primer pairs designed from cloned RAPD/AFLP bands."}}},{"id":29,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following statements with regard to glyoxylate cycle is INCORRECT?"}],"options":[{"key":"1","text":"It is absent in humans."},{"key":"2","text":"It occurs in specialized microsomes called glyoxysomes."},{"key":"3","text":"This cycle allows for the synthesis of sugars from fatty acids."},{"key":"4","text":"It involves enzymes of both the glyoxysome and the mitochondrion."}],"answer":"2","explanation":{"correct":"Glyoxysomes are specialised <b>peroxisomes</b> (microbodies) of germinating oil seeds. \"Microsomes\" are vesicles of fragmented ER produced by cell homogenisation, so calling glyoxysomes microsomes is incorrect.","wrong":{"1":"Correct: vertebrates lack isocitrate lyase and malate synthase.","3":"Correct: by bypassing the two decarboxylations of the TCA cycle, acetyl-CoA yields net succinate/oxaloacetate for gluconeogenesis.","4":"Correct: succinate made in the glyoxysome is converted to malate/oxaloacetate in mitochondria."}}},{"id":30,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following statements regarding cytoskeleton proteins is INCORRECT?"}],"options":[{"key":"1","text":"Actin and tubulin proteins appear to have arisen from single-copy genes, present before multicellular eukaryotes diverged."},{"key":"2","text":"Tubulin specifically binds ATP, while actin binds preferentially to GTP."},{"key":"3","text":"FtsZ, a tubulin relative, forms a filamentous ring needed to effect cell division in certain prokaryotic species."},{"key":"4","text":"MreB, an actin relative, forms filaments required for the cell shape in certain prokaryotic species."}],"answer":"2","explanation":{"correct":"It is the other way round: tubulin is a GTPase (β-tubulin hydrolyses GTP) and actin binds and hydrolyses ATP.","wrong":{"1":"Correct: both are ancient, highly conserved families traceable to the common eukaryotic ancestor.","3":"Correct: FtsZ forms the Z-ring at the division site.","4":"Correct: MreB filaments direct lateral cell-wall synthesis in rod-shaped bacteria."}}},{"id":31,"part":"B","unit":3,"blocks":[{"t":"p","h":"A novel organism synthesizes proteins using ribosomes from the C-terminal end to the N-terminal end rather than the usual direction (N- to C-terminus). Which main chain atom will be the nucleophile for the reaction to form peptide bonds?"}],"options":[{"key":"1","text":"Nitrogen of the amine group"},{"key":"2","text":"Carbon of the carboxyl group"},{"key":"3","text":"Oxygen of the carboxyl group"},{"key":"4","text":"Alpha-carbon (Cα)"}],"answer":"1","explanation":{"correct":"A peptide bond always forms by nucleophilic attack of an α-amino nitrogen on an activated carbonyl carbon. Reversing the direction only changes which partner carries which group: the free amine at the N-terminus of the growing chain would attack the ester-activated carbonyl of the incoming aminoacyl-tRNA. The nucleophile is still the amine nitrogen.","wrong":{"2":"The carbonyl carbon is the electrophile, not the nucleophile.","3":"Carboxyl oxygen does not form the amide bond.","4":"Cα is not nucleophilic."}}},{"id":32,"part":"B","unit":10,"blocks":[{"t":"p","h":"Many marine mammals communicate over several kilometres in the ocean. This is due to"}],"options":[{"key":"1","text":"their ability to communicate using ultrasound."},{"key":"2","text":"the higher density of water compared to air."},{"key":"3","text":"lower oxygen levels in the open ocean."},{"key":"4","text":"water filtering out high-frequency sounds."}],"answer":"2","explanation":{"correct":"Water is far denser and less compressible than air, so sound travels about 4.5 times faster (~1500 m s⁻¹) and is attenuated much less, especially at low frequencies. Baleen whales exploit this with low-frequency calls that propagate over very long distances, aided by the SOFAR channel.","wrong":{"1":"Ultrasound (used in echolocation) attenuates fastest, so it is short-range.","3":"Oxygen level has no bearing on sound propagation.","4":"Water does absorb high frequencies more, but that is a consequence of propagation in water, not the reason long-distance communication is possible."}}},{"id":33,"part":"B","unit":8,"blocks":[{"t":"p","h":"A mutation in a Drosophila gene causes a reduction in eye size, if animals are grown at 29°C but not at 18°C. This happens even if the animals bear a single copy of this mutation. Based on this information, this mutation can be described as:"}],"options":[{"key":"1","text":"Temperature insensitive, dominant"},{"key":"2","text":"Temperature sensitive, recessive"},{"key":"3","text":"Temperature insensitive, recessive"},{"key":"4","text":"Temperature sensitive, dominant"}],"answer":"4","explanation":{"correct":"The phenotype appears at the restrictive temperature (29 °C) but not at the permissive one (18 °C), so it is temperature-sensitive. It is expressed in heterozygotes carrying a single copy, so it is dominant.","wrong":{"1":"The phenotype depends on temperature.","2":"One copy is enough, so it is not recessive.","3":"Wrong on both counts."}}},{"id":34,"part":"B","unit":3,"blocks":[{"t":"p","h":"The majority of modifications on histone molecules happen at their ____"}],"options":[{"key":"1","text":"N-terminal tail."},{"key":"2","text":"C-terminal tail."},{"key":"3","text":"Globular core."},{"key":"4","text":"Spread equally throughout the polypeptide."}],"answer":"1","explanation":{"correct":"Most post-translational marks (acetylation, methylation, phosphorylation of lysine, arginine and serine residues) lie on the flexible N-terminal tails, which protrude from the nucleosome and are accessible to writers and readers.","wrong":{"2":"C-terminal marks exist (e.g. H2A K119ub, H2B K120ub) but are fewer.","3":"Core marks (e.g. H3K56ac, H3K79me) exist but are a minority.","4":"Modifications are concentrated in the tails."}}},{"id":35,"part":"B","unit":10,"blocks":[{"t":"p","h":"Within a broadly distributed taxonomic clade, populations and species of larger size are generally found in colder environments, while populations and species of smaller size are typically found in warmer regions. This observation is commonly referred to as:"}],"options":[{"key":"1","text":"Allen's rule"},{"key":"2","text":"Bergmann's rule"},{"key":"3","text":"Gause's rule"},{"key":"4","text":"Gloger's rule"}],"answer":"2","explanation":{"correct":"Bergmann's rule (1847): larger body size in colder climates, explained by a lower surface-area-to-volume ratio that reduces heat loss.","wrong":{"1":"Allen's rule concerns shorter appendages (ears, limbs) in colder climates.","3":"Gause's rule is competitive exclusion.","4":"Gloger's rule relates darker pigmentation to warm, humid climates."}}},{"id":36,"part":"B","unit":4,"blocks":[{"t":"p","h":"The CaM Kinase II acts as a molecular memory device as well as a frequency decoder of Ca<sup>2+</sup> oscillation. Which one of the following statements regarding CaM Kinase II is INCORRECT?"}],"options":[{"key":"1","text":"CaM Kinase II activity increases as a function of Ca<sup>2+</sup> pulse frequency."},{"key":"2","text":"CaM Kinase II requires Ca<sup>2+</sup> and Calmodulin to remain in an active state."},{"key":"3","text":"A brain-specific CaM Kinase II knockout mouse will have difficulty in remembering where things are."},{"key":"4","text":"The molecular memory function is lost in an autophosphorylation defective CaM Kinase II."}],"answer":"2","explanation":{"correct":"Once activated, neighbouring subunits of the dodecameric holoenzyme autophosphorylate each other on Thr286 (αCaMKII). This makes the kinase <b>autonomous</b>: it stays active after Ca²⁺/calmodulin has dissociated. That persistence is the basis of its \"memory\", so the statement that it needs Ca²⁺/CaM to remain active is incorrect.","wrong":{"1":"Correct: higher pulse frequency leaves less time for dephosphorylation between pulses, so autonomous activity accumulates (De Koninck &amp; Schulman 1998).","3":"Correct: αCaMKII-null mice are impaired in hippocampal spatial learning (Silva et al. 1992).","4":"Correct: the T286A mutant loses autonomy, LTP and spatial learning (Giese et al. 1998)."}}},{"id":37,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following acetylcholine receptors is located in the nodal tissue of heart?"}],"options":[{"key":"1","text":"M<sub>3</sub>"},{"key":"2","text":"N<sub>M</sub>"},{"key":"3","text":"M<sub>2</sub>"},{"key":"4","text":"M<sub>4</sub>"}],"answer":"3","explanation":{"correct":"SA and AV nodal cells express M<sub>2</sub> muscarinic receptors (G<sub>i/o</sub>-coupled). Vagal ACh released onto them opens GIRK (I<sub>K,ACh</sub>) channels and lowers cAMP, slowing heart rate and AV conduction.","wrong":{"1":"M<sub>3</sub> receptors are on smooth muscle, glands and endothelium.","2":"N<sub>M</sub> receptors are on the skeletal-muscle end plate.","4":"M<sub>4</sub> receptors are mainly in the CNS."}}},{"id":38,"part":"B","unit":10,"blocks":[{"t":"p","h":"Cleaner fish remove parasites from larger fish. Which evolutionary mechanism most likely maintains this interaction?"}],"options":[{"key":"1","text":"Kin selection"},{"key":"2","text":"Mutualism"},{"key":"3","text":"Direct competition"},{"key":"4","text":"Character displacement"}],"answer":"2","explanation":{"correct":"Both partners gain: the cleaner (e.g. <i>Labroides dimidiatus</i>) gets food and the client loses parasites. Interspecific reciprocal benefit is mutualism, stabilised by partner choice and punishment of cheating cleaners that bite mucus (Bshary &amp; Grutter 2006, <i>Nature</i> 441:975).","wrong":{"1":"Kin selection requires relatedness; the partners belong to different species.","3":"There is no shared limiting resource being contested.","4":"Character displacement concerns competing species diverging."}}},{"id":39,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following microbes is an obligate biotroph?"}],"options":[{"key":"1","text":"<i>Botrytis cinerea</i>"},{"key":"2","text":"<i>Phytophthora infestans</i>"},{"key":"3","text":"<i>Puccinia graminis</i>"},{"key":"4","text":"<i>Trichoderma harzianum</i>"}],"answer":"3","explanation":{"correct":"Rust fungi such as <i>Puccinia graminis</i> (stem rust of wheat) can grow and complete their life cycle only on living host tissue, feeding through haustoria. They cannot be cultured on ordinary media: they are obligate biotrophs.","wrong":{"1":"<i>Botrytis</i> (grey mould) is a classic necrotroph.","2":"<i>Phytophthora infestans</i> is a hemibiotroph and can be cultured.","4":"<i>Trichoderma</i> is a free-living saprotroph and mycoparasite used in biocontrol."}}},{"id":40,"part":"B","unit":10,"blocks":[{"t":"p","h":"<i>Saara hardwickii</i>, a spiny-tailed lizard, is a diurnal, ground-dwelling species currently known from the Indian subcontinent. It is endemic to which one of the following habitats?"}],"options":[{"key":"1","text":"Rainforests of Eastern Himalayas"},{"key":"2","text":"Dry deciduous forests of central India"},{"key":"3","text":"Moist deciduous forests of Western Ghats"},{"key":"4","text":"Thar desert of India"}],"answer":"4","explanation":{"correct":"The Indian spiny-tailed lizard is an arid-zone, burrow-dwelling herbivorous agamid of the Thar Desert and adjoining arid plains of Rajasthan, Gujarat and Pakistan.","wrong":{"1":"It is not a forest species.","2":"It is not a forest species.","3":"It is not a forest species."}}},{"id":41,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following is generated in skeletal muscle cells by the single quanta of acetylcholine released from the motor nerve terminals?"}],"options":[{"key":"1","text":"Inhibitory post-synaptic potential"},{"key":"2","text":"Inhibitory junction potential"},{"key":"3","text":"Endplate potential"},{"key":"4","text":"Miniature endplate potential"}],"answer":"4","explanation":{"correct":"Fatt &amp; Katz (1952) recorded small (~0.5–1 mV) spontaneous depolarisations at the resting end plate, each produced by one vesicle (quantum) of ACh. These are miniature endplate potentials. A nerve impulse releases ~100+ quanta together to give the full endplate potential.","wrong":{"1":"ACh at the vertebrate neuromuscular junction is excitatory (nicotinic).","2":"Inhibitory junction potentials occur in smooth muscle, not vertebrate skeletal muscle.","3":"The EPP is the summed response to many quanta."}}},{"id":42,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following statements about human chorionic gonadotropin is INCORRECT?"}],"options":[{"key":"1","text":"It contains galactose and hexosamine."},{"key":"2","text":"Its α-subunit is identical in TSH."},{"key":"3","text":"Its β-subunit is smaller than α-subunit in size."},{"key":"4","text":"It is primarily luteinizing in nature."}],"answer":"3","explanation":{"correct":"hCG β (145 amino acids, with a long glycosylated C-terminal extension) is <b>larger</b> than the α-subunit (92 amino acids).","wrong":{"1":"Correct: hCG is a heavily glycosylated glycoprotein (N- and O-linked chains containing galactose, hexosamines and sialic acid).","2":"Correct: hCG, LH, FSH and TSH share the same α-subunit (CGA gene); the β-subunit confers specificity.","4":"Correct: hCG acts on the LH/CG receptor and rescues the corpus luteum."}}},{"id":43,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following is NOT a major phospholipid in mammalian plasma membrane?"}],"options":[{"key":"1","text":"Phosphatidylinositol"},{"key":"2","text":"Phosphatidylserine"},{"key":"3","text":"Sphingomyelin"},{"key":"4","text":"Cholesterol"}],"answer":"1","explanation":{"correct":"NTA's key gives phosphatidylinositol. Standard texts (Alberts, <i>Molecular Biology of the Cell</i>) list four major phospholipids of mammalian plasma membranes: phosphatidylcholine, phosphatidylethanolamine, phosphatidylserine and sphingomyelin. Together they make up more than half the membrane lipid. PI and its phosphorylated forms are functionally vital but quantitatively minor (a few percent).","wrong":{"2":"PS is one of the four major phospholipids (concentrated in the inner leaflet).","3":"Sphingomyelin is a major phospholipid of the outer leaflet.","4":"Cholesterol is a major membrane lipid but a sterol, not a phospholipid."},"notes":["Strictly, cholesterol is also \"not a major phospholipid\". The question intends a phospholipid that is not quantitatively major, and NTA's final key accepts only option 1."]}},{"id":44,"part":"B","unit":13,"blocks":[{"t":"p","h":"Which experiment would best validate the bioremediation potential of a microbial strain degrading oil spills in seawater?"}],"options":[{"key":"1","text":"Using seawater without oil contamination to monitor microbial growth."},{"key":"2","text":"Testing microbial growth in seawater with added nutrients but no oil."},{"key":"3","text":"Monitoring oil concentration in a system inoculated with microbes versus an uninoculated system."},{"key":"4","text":"Comparing microbial growth in aerated versus non-aerated seawater samples."}],"answer":"3","explanation":{"correct":"Bioremediation is shown by the disappearance of the pollutant attributable to the organism. That requires measuring hydrocarbon concentration over time in inoculated microcosms against an uninoculated (or sterile) control, which separates biodegradation from evaporation, dispersion and abiotic loss.","wrong":{"1":"Without oil there is nothing to degrade.","2":"Growth on nutrients alone does not show oil degradation.","4":"This tests oxygen requirement, not degradation of the pollutant."}}},{"id":45,"part":"B","unit":8,"blocks":[{"t":"p","h":"UV mutagenesis was performed to isolate mutants of the <i>lacZ</i> gene. The mutation rate of this gene is 1 × 10<sup>−4</sup> per cell division. Assuming that an <i>E. coli</i> culture was initiated from a culture density of 1 × 10<sup>2</sup> cells and grown to a density of 1 × 10<sup>6</sup> cells, how many <i>lacZ</i> mutants are expected in this population?"}],"options":[{"key":"1","text":"~1"},{"key":"2","text":"~10"},{"key":"3","text":"~100"},{"key":"4","text":"~1000"}],"answer":"3","explanation":{"correct":"NTA's final key is ~1. This corresponds to multiplying the mutation rate by the <i>fold</i> increase in cell number: (10<sup>6</sup>/10<sup>2</sup>) × 10<sup>−4</sup> = 10<sup>4</sup> × 10<sup>−4</sup> ≈ 1.","notes":["Caution, for your own understanding: in standard fluctuation-analysis terms, the number of cell divisions needed to grow from 10² to 10⁶ cells is N − N₀ ≈ 10⁶. The expected number of mutational <i>events</i> is therefore μ(N − N₀) ≈ 10⁻⁴ × 10⁶ ≈ 100. Because early mutants keep dividing, the expected number of mutant <i>cells</i> is larger still, ≈ μN·ln(N/N₀) (Luria &amp; Delbrück 1943; Lea &amp; Coulson 1949). The key is followed here for scoring, but the textbook expectation is ~100 events."]}},{"id":46,"part":"B","unit":4,"blocks":[{"t":"p","h":"Fill in the blanks:"},{"t":"p","h":"Glioblastomas, oligodendrogliomas, and astrocytomas harbour mutations in isocitrate dehydrogenase (IDH). The IDH mutations found in these cancers cause the enzyme to convert isocitrate into the oncometabolite, _____, which accumulates in cancer cells. This oncometabolite works by inhibiting several enzymes that require _____ for their function."}],"options":[{"key":"1","text":"2-hydroxyglutarate, succinate"},{"key":"2","text":"2-hydroxybutyrate, α-ketoglutarate"},{"key":"3","text":"2-hydroxyglutarate, 2-hydroxybutyrate"},{"key":"4","text":"2-hydroxyglutarate, α-ketoglutarate"}],"answer":"4","explanation":{"correct":"Heterozygous IDH1 R132 / IDH2 R172 mutations give the enzyme a neomorphic activity: it reduces α-KG to D-2-hydroxyglutarate (Dang et al. 2009, <i>Nature</i> 462:739). D-2HG is a structural analogue of α-KG and competitively inhibits α-KG-dependent dioxygenases, including TET DNA demethylases and JmjC histone demethylases. The result is a hypermethylated (G-CIMP) state (Xu et al. 2011, <i>Cancer Cell</i> 19:17).","wrong":{"1":"Succinate is a product of these dioxygenases (and itself an oncometabolite in SDH-deficient tumours), not their co-substrate.","2":"2-Hydroxybutyrate is unrelated to IDH.","3":"2-Hydroxybutyrate is not a dioxygenase co-substrate."}}},{"id":47,"part":"B","unit":9,"blocks":[{"t":"p","h":"The order Psilotales can be identified by which one of the following characteristics?"}],"options":[{"key":"1","text":"Leafless and rootless body with a dichotomously branching stem"},{"key":"2","text":"Very large fronds, some reaching 4.5 m or more in length"},{"key":"3","text":"Scale leaves that are borne in whorls at the node"},{"key":"4","text":"A plant body that consists of microphylls and roots only"}],"answer":"1","explanation":{"correct":"<i>Psilotum</i> (whisk fern) has no true roots (only a rhizome with rhizoids and mycorrhizae) and no true leaves (only tiny enations), with a dichotomously branching aerial stem bearing synangia.","wrong":{"2":"Very large fronds describe marattioid or tree ferns.","3":"Whorled scale leaves at nodes describe <i>Equisetum</i>.","4":"Microphylls with roots describe lycophytes (<i>Lycopodium</i>, <i>Selaginella</i>)."}}},{"id":48,"part":"B","unit":14,"blocks":[{"t":"p","h":"Which one of the following techniques can identify acetylation on a lysine residue of a protein?"}],"options":[{"key":"1","text":"Mass spectrometry"},{"key":"2","text":"SDS-PAGE"},{"key":"3","text":"Light scattering"},{"key":"4","text":"CD spectroscopy"}],"answer":"1","explanation":{"correct":"Lysine acetylation adds 42.011 Da. In tandem MS of proteolytic peptides, this mass shift is detected and localised to a specific residue from b/y fragment ions; acetyl-lysine also gives a diagnostic immonium ion at m/z 126.","wrong":{"2":"SDS-PAGE cannot resolve a 42 Da change or identify the residue.","3":"Light scattering reports size and oligomeric state.","4":"CD spectroscopy reports secondary structure."}}},{"id":49,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following blood cell types is formed from megakaryocyte during development of blood cells from bone marrow?"}],"options":[{"key":"1","text":"Monocytes"},{"key":"2","text":"Neutrophils"},{"key":"3","text":"Eosinophils"},{"key":"4","text":"Platelets"}],"answer":"4","explanation":{"correct":"Polyploid megakaryocytes extend proplatelet processes into marrow sinusoids and shed platelets (thrombocytes) into the circulation, under thrombopoietin control.","wrong":{"1":"Monocytes come from monoblasts.","2":"Neutrophils come from myeloblasts.","3":"Eosinophils come from myeloblasts."}}},{"id":50,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following modifications in their native system does NOT lead to translation inhibition?"}],"options":[{"key":"1","text":"Nucleotide addition resulting in incorporation of a stem-loop structure in the mRNA upstream of the Shine-Dalgarno sequence."},{"key":"2","text":"Nucleotide addition resulting in the Shine-Dalgarno sequence being a part of a stem-loop structure in the mRNA."},{"key":"3","text":"Expression of an eIF2 mutant that mimics its phosphorylated state."},{"key":"4","text":"Mutation that leads to decrease in the processivity of capping enzyme that leaves numerous mRNAs devoid of CAP structure."}],"answer":"1","explanation":{"correct":"Bacterial 30S subunits bind directly at the Shine–Dalgarno/start-codon region, so a hairpin placed <i>upstream</i> of the SD, outside the ribosome footprint, leaves initiation essentially unaffected.","wrong":{"2":"Sequestering the SD in a stem-loop blocks 30S binding (the riboswitch and thermometer principle).","3":"Phospho-eIF2α tightly binds and inhibits eIF2B, depleting eIF2·GTP·Met-tRNA<sub>i</sub> and inhibiting global translation.","4":"Uncapped mRNAs are not recognised by eIF4E and are also degraded, so cap-dependent translation falls."}}},{"id":51,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following statements about peripheral lymph nodes is INCORRECT?"}],"options":[{"key":"1","text":"They contain fibroblast reticular cells that form a conduit system to guide cell movement within the node."},{"key":"2","text":"They are responsible for immune responses to blood-borne pathogens."},{"key":"3","text":"T cells encounter antigen presented on dendritic cells in the paracortex of lymph nodes."},{"key":"4","text":"They contain B cells in special areas called follicles."}],"answer":"2","explanation":{"correct":"Lymph nodes filter <b>lymph</b> and respond to antigens arriving from tissues via afferent lymphatics. Blood-borne antigens are filtered by the <b>spleen</b>.","wrong":{"1":"Correct: the FRC network and conduits guide T cells and DCs and channel small antigens.","3":"Correct: the paracortex is the T-cell zone where DCs present antigen.","4":"Correct: B cells reside in cortical follicles and form germinal centres."}}},{"id":52,"part":"B","unit":10,"blocks":[{"t":"p","h":"As per the India State of Forest Report 2021, the percentage cover of 'very dense forests' as a component of the country's total geographical area is:"}],"options":[{"key":"1","text":"3.04"},{"key":"2","text":"9.33"},{"key":"3","text":"9.44"},{"key":"4","text":"21.71"}],"answer":"1","explanation":{"correct":"ISFR 2021 (Forest Survey of India): very dense forest (canopy density ≥70%) covers 99,779 km², i.e. 3.04% of India's geographical area.","wrong":{"2":"9.33% is moderately dense forest.","3":"9.44% matches no ISFR 2021 class (open forest is 9.34%).","4":"21.71% is total forest cover (VDF + MDF + OF)."}}},{"id":53,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following morphological characters can help you differentiate Leptosporangiate ferns from the Eusporangiate ferns?"}],"options":[{"key":"1","text":"Presence and absence of sporangium"},{"key":"2","text":"Ploidy of the spores"},{"key":"3","text":"The number of cells from which the sporangium is formed"},{"key":"4","text":"The total number of alternations of generations recorded in a single life cycle"}],"answer":"3","explanation":{"correct":"A leptosporangium develops from a <b>single</b> superficial initial cell and has a one-cell-thick wall, few spores and an annulus. A eusporangium arises from <b>several</b> initials and has a multilayered wall and many spores (Goebel's classical distinction).","wrong":{"1":"Both groups have sporangia.","2":"Spores are haploid in both.","4":"Both show one alternation of generations per life cycle."}}},{"id":54,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following statements about RNA polymerase in eukaryotes is INCORRECT?"}],"options":[{"key":"1","text":"RNA polymerase I synthesizes 18S, 5.8S and 28S rRNAs."},{"key":"2","text":"RNA polymerase II synthesizes messenger RNA (mRNA)."},{"key":"3","text":"RNA polymerase II requires a sigma factor (σ) to initiate transcription."},{"key":"4","text":"RNA polymerase III synthesizes 5S rRNA and tRNA."}],"answer":"3","explanation":{"correct":"σ factors belong to bacterial RNA polymerase. Eukaryotic Pol II is recruited by general transcription factors (TFIIA, B, D, E, F and H) and Mediator.","wrong":{"1":"Correct: Pol I transcribes the 45S pre-rRNA, processed into 18S, 5.8S and 28S.","2":"Correct.","4":"Correct: Pol III also makes U6 snRNA and 7SL RNA."}}},{"id":55,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following is likely to enter a pure phospholipid bilayer?"}],"options":[{"key":"1","text":"CO<sub>2</sub> and Diethyl urea"},{"key":"2","text":"Water and Glucose"},{"key":"3","text":"Lysine and Ethanol"},{"key":"4","text":"Urea and Chloride ions"}],"answer":"1","explanation":{"correct":"Permeability of a protein-free bilayer rises with hydrophobicity and small size. CO₂ is a small non-polar gas and crosses readily. Diethylurea is much more lipophilic than urea and permeates far faster: the classic Collander–Overton series (Alberts, Fig. 11-1) shows permeability rising as hydrophobic ethyl groups are added to urea.","wrong":{"2":"Water permeates slowly, but glucose essentially does not.","3":"Lysine is a charged amino acid and cannot cross.","4":"Chloride, an ion, is essentially impermeant; urea crosses only slowly."}}},{"id":56,"part":"B","unit":1,"blocks":[{"t":"p","h":"The Citric acid cycle (TCA) operates only in the presence of molecular oxygen (O<sub>2</sub>). This is because"}],"options":[{"key":"1","text":"O<sub>2</sub> activates enzymatic dehydrogenation reactions in the cycle."},{"key":"2","text":"O<sub>2</sub> accepts electrons from electron transport chain, allowing reoxidation of NADH to NAD<sup>+</sup>."},{"key":"3","text":"O<sub>2</sub> removes toxic by-products of the TCA cycle."},{"key":"4","text":"O<sub>2</sub> activates ATP synthase."}],"answer":"2","explanation":{"correct":"No TCA step uses O₂ directly. The cycle needs a continuous supply of NAD⁺ and FAD for its four dehydrogenations. These are regenerated only when the electron transport chain passes electrons to O₂ (complex IV). Without O₂, NADH accumulates and the cycle stops.","wrong":{"1":"O₂ does not activate the dehydrogenases.","3":"The TCA cycle makes no toxic by-product that O₂ removes.","4":"ATP synthase is driven by the proton-motive force, not activated by O₂."}}},{"id":57,"part":"B","unit":3,"blocks":[{"t":"p","h":"Two types of mutant <i>E. coli</i> were identified: in the hypermethylation mutant (type A), DNA is methylated at the GATC sequences as soon as daughter DNA is synthesized; and in the second type, GATC sequences are never methylated (type B)."},{"t":"p","h":"Which mutant will have a greater effect on the MMR system, leading to the accumulation of spontaneous mutations?"}],"options":[{"key":"1","text":"Type A &gt; Type B"},{"key":"2","text":"Type B &gt; Type A"},{"key":"3","text":"Type A = Type B"},{"key":"4","text":"Type B mutants will not accumulate spontaneous mutations"}],"answer":"1","explanation":{"correct":"MutH nicks the <b>unmethylated</b> strand of a hemimethylated GATC, which directs repair to the newly made strand. If the new strand is methylated immediately (Dam overproduction), the transient hemimethylated window disappears and MutH has no signal, so mismatches escape repair. Dam-overproducing strains are strong mutators (Herman &amp; Modrich 1981, <i>J Bacteriol</i> 145:644). In <i>dam</i>⁻ cells (type B), MutH can still nick either unmethylated strand. Repair then becomes non-directional, so about half of corrections are \"right\", and the mutator effect is milder.","wrong":{"2":"Unmethylated DNA still allows (undirected) repair, so the effect is weaker.","3":"The effects differ in magnitude.","4":"<i>dam</i>⁻ mutants do show a modest mutator phenotype."}}},{"id":58,"part":"B","unit":5,"blocks":[{"t":"p","h":"Which one of the following statements regarding mutations in the mitochondria during aging is INCORRECT?"}],"options":[{"key":"1","text":"Mutations in mitochondrial genome lead to defects in energy production."},{"key":"2","text":"The mutation rate in mitochondria is much higher than that in the nucleus."},{"key":"3","text":"Mutations reduce ROS production since electron transport is faulty."},{"key":"4","text":"There is an enhanced rate of apoptosis in cells with mutant mitochondria."}],"answer":"3","explanation":{"correct":"Defective respiratory complexes cause electron leakage, so ROS production generally <b>increases</b>. This feeds the \"vicious cycle\" of the mitochondrial free-radical theory of aging.","wrong":{"1":"Correct: mtDNA encodes 13 OXPHOS subunits.","2":"Correct: mtDNA lacks protective histones, sits near ROS sources and has limited repair; its mutation rate is roughly 10–20× that of nuclear DNA.","4":"Correct: dysfunctional mitochondria release cytochrome <i>c</i> more readily; the mtDNA-mutator (PolgA) mouse shows increased apoptosis and premature aging (Kujoth et al. 2005, <i>Science</i> 309:481)."}}},{"id":59,"part":"B","unit":4,"blocks":[{"t":"p","h":"Live vaccines are generally used to protect against which one of the following viruses?"}],"options":[{"key":"1","text":"Hepatitis A"},{"key":"2","text":"Hepatitis B"},{"key":"3","text":"Rabies"},{"key":"4","text":"Smallpox"}],"answer":"4","explanation":{"correct":"Smallpox was eradicated using a live vaccinia virus vaccine, the archetypal live viral vaccine.","wrong":{"1":"Hepatitis A vaccines in general use are inactivated (formalin-killed); live attenuated HAV vaccines exist in China but are not the norm.","2":"Hepatitis B vaccine is a recombinant HBsAg subunit vaccine.","3":"Rabies vaccines (e.g. HDCV, PCECV) are inactivated."}}},{"id":60,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following is an example of character displacement?"}],"options":[{"key":"1","text":"Two sympatric lizards with similar morphologies consume the same insects."},{"key":"2","text":"Two sympatric birds evolve distinct beak shapes to consume seeds of different plants."},{"key":"3","text":"A predator evolves higher visual acuity to catch camouflaged prey."},{"key":"4","text":"Two plant species have similar flower shapes to attract the same pollinators."}],"answer":"2","explanation":{"correct":"Character displacement (Brown &amp; Wilson 1956) is greater divergence of traits in sympatry than in allopatry, driven by competition for shared resources. The textbook case is beak depth in Galápagos ground finches (<i>Geospiza fortis</i> and <i>G. fuliginosa</i>; Grant &amp; Grant 2006, <i>Science</i> 313:224).","wrong":{"1":"This describes overlap and competition without divergence.","3":"This is predator–prey coevolution (an arms race).","4":"This is convergence (pollinator-mediated), the opposite of displacement."}}},{"id":61,"part":"B","unit":8,"blocks":[{"t":"p","h":"The disease phenylketonuria is caused by the null allele of the gene phenylalanine hydroxylase (PAH). This is an example of a recessive mutation. Which one of the following terms is the best description of the wild type allele of PAH?"}],"options":[{"key":"1","text":"Gain-of-function"},{"key":"2","text":"Haplosufficient"},{"key":"3","text":"Epistatic"},{"key":"4","text":"Allele with additive effect"}],"answer":"2","explanation":{"correct":"Heterozygous carriers are unaffected, so one functional PAH allele makes enough enzyme. This is haplosufficiency, the usual reason loss-of-function alleles of enzymes are recessive (Kacser &amp; Burns 1981).","wrong":{"1":"The wild-type allele is the normal function, not a gain.","3":"Epistasis describes interaction between different genes.","4":"An additive allele would make heterozygotes intermediate."}}},{"id":62,"part":"B","unit":5,"blocks":[{"t":"p","h":"Which is the correct hierarchy of gene activity in early Drosophila segmentation?"}],"options":[{"key":"1","text":"Gap, pair-rule, segment polarity, maternal"},{"key":"2","text":"Maternal, gap, pair-rule, segment polarity"},{"key":"3","text":"Maternal, pair-rule, gap, segment polarity"},{"key":"4","text":"Segment polarity, pair-rule, gap, maternal"}],"answer":"2","explanation":{"correct":"Maternal effect gradients (Bicoid, Nanos, Hunchback, Caudal) regulate gap genes (<i>hb</i>, <i>Kr</i>, <i>kni</i>, <i>gt</i>). Gap proteins regulate the stripes of pair-rule genes (<i>eve</i>, <i>ftz</i>), which in turn set up the segment-polarity genes (<i>en</i>, <i>wg</i>, <i>hh</i>) (Nüsslein-Volhard &amp; Wieschaus 1980).","wrong":{"1":"Maternal genes act first, not last.","3":"Gap genes act before pair-rule genes.","4":"This is the reverse order."}}},{"id":63,"part":"B","unit":5,"blocks":[{"t":"p","h":"The epigenetic regulators DEMETER (DME) and MEDEA (MEA) act synergistically to repress endosperm development in the absence of double fertilization during seed development in Arabidopsis. Which one of the following options is the correct enzymatic function of DME and MEA?"}],"options":[{"key":"1","text":"DME is a DNA glycosylase; MEA is a DNA methyl transferase."},{"key":"2","text":"DME is a DNA methyl transferase; MEA is a histone methyl transferase."},{"key":"3","text":"DME is a histone methyl transferase; MEA is a DNA methyl transferase."},{"key":"4","text":"DME is a DNA glycosylase; MEA is a histone methyl transferase."}],"answer":"4","explanation":{"correct":"DME is a 5-methylcytosine DNA glycosylase that removes methylation (base-excision demethylation) in the central cell (Choi et al. 2002, <i>Cell</i> 110:33). MEA is the SET-domain H3K27 methyltransferase of the FIS-PRC2 complex (homologous to E(z)), which represses autonomous endosperm proliferation.","wrong":{"1":"MEA methylates histones, not DNA.","2":"DME removes rather than adds DNA methylation.","3":"Both functions are swapped."}}},{"id":64,"part":"B","unit":8,"blocks":[{"t":"p","h":"The dominant and recessive alleles of a gene are 'A' and 'a', respectively. In 1000 offspring, if 500 are 'aa' and 500 are of the other genotypes, which one of the following is the most likely combination of parental genotypes?"}],"options":[{"key":"1","text":"Aa and Aa"},{"key":"2","text":"AA and Aa"},{"key":"3","text":"Aa and aa"},{"key":"4","text":"AA and aa"}],"answer":"3","explanation":{"correct":"A 1:1 ratio of Aa : aa is the testcross ratio, Aa × aa.","wrong":{"1":"Aa × Aa gives 25% aa.","2":"AA × Aa gives no aa.","4":"AA × aa gives only Aa."}}},{"id":65,"part":"B","unit":9,"blocks":[{"t":"p","h":"What type of invertebrate fossils, commonly found in the Spiti Valley of India, are characteristic of the Cambrian era?"}],"options":[{"key":"1","text":"Ammonites"},{"key":"2","text":"Trilobites"},{"key":"3","text":"Mosquitoes"},{"key":"4","text":"Glossopteris"}],"answer":"2","explanation":{"correct":"Trilobites are the index fossils of the Cambrian. The Parahio Valley section in Spiti (Tethyan Himalaya) yields rich Cambrian trilobite faunas.","wrong":{"1":"Ammonites (abundant in Spiti's Jurassic Spiti Shale) are Mesozoic.","3":"Mosquitoes are Mesozoic and later insects, not characteristic Spiti fossils.","4":"<i>Glossopteris</i> is a Permian seed-fern (a plant), not an invertebrate."}}},{"id":66,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following types of interactions will be predominantly contributing to the stability of a nucleosome?"}],"options":[{"key":"1","text":"Hydrogen bonds between DNA base pairs and serine/threonine residues of histones."},{"key":"2","text":"van der Waal's interactions between DNA base pairs and hydrophobic residues of histones."},{"key":"3","text":"Hydrogen bonds between DNA phosphate backbone and the main chain atoms of histones."},{"key":"4","text":"Electrostatic interactions involving DNA phosphate backbone and lysine residues of histones."}],"answer":"4","explanation":{"correct":"Histone–DNA contacts in the nucleosome are largely sequence-independent and backbone-mediated. The dominant energetic contribution is electrostatic, between basic Lys/Arg side chains and the phosphate backbone, which neutralises its charge so the DNA can wrap 1.65 times around the octamer (Luger et al. 1997, <i>Nature</i> 389:251).","wrong":{"1":"Base-specific hydrogen bonds would make binding sequence-specific; nucleosomes are not.","2":"The bases face inward and do not form a hydrophobic interface with histones.","3":"Main-chain amide–phosphate hydrogen bonds do occur (at the 14 contact sites) but contribute less than the lysine/arginine electrostatics."}}},{"id":67,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following statements is true regarding β-oxidation of fatty acids?"}],"options":[{"key":"1","text":"It occurs in the intermembrane space (IMS) region of mitochondria."},{"key":"2","text":"All the reactions are same for the saturated and unsaturated fatty acids."},{"key":"3","text":"Fatty acids are oxidized at C-3 position to remove a two-carbon unit."},{"key":"4","text":"Lipoprotein lipase catalyzes the first step."}],"answer":"3","explanation":{"correct":"The β-carbon (C-3) is oxidised to a ketone (via dehydrogenation, hydration and a second dehydrogenation). Thiolase then cleaves between C-2 and C-3, releasing acetyl-CoA.","wrong":{"1":"β-Oxidation is in the mitochondrial matrix (and in peroxisomes).","2":"Unsaturated fatty acids need extra enzymes (enoyl-CoA isomerase, 2,4-dienoyl-CoA reductase).","4":"The first step is acyl-CoA dehydrogenase; lipoprotein lipase hydrolyses triglycerides in the capillaries."}}},{"id":68,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following events occurs during the light reaction of photosynthesis and directly contributes to the formation of ATP?"}],"options":[{"key":"1","text":"Splitting of water molecules into oxygen, protons, and electrons"},{"key":"2","text":"Transfer of electrons from Photosystem I to NADP<sup>+</sup> to form NADPH"},{"key":"3","text":"Carbon fixation by the enzyme RuBisCO in the stroma"},{"key":"4","text":"Establishment of a proton gradient across the thylakoid membrane"}],"answer":"4","explanation":{"correct":"ATP synthesis by CF₀CF₁ ATP synthase is driven <i>directly</i> by the proton-motive force across the thylakoid membrane (Mitchell's chemiosmosis; Jagendorf's acid-bath experiment, 1966).","wrong":{"1":"Water splitting contributes lumenal protons, but it is the resulting gradient that drives the synthase.","2":"NADP⁺ reduction consumes stromal protons and makes NADPH, not ATP.","3":"Carbon fixation is a dark (Calvin–Benson) reaction that consumes ATP."}}},{"id":69,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which of the following Vitamin B complex derivatives constitute the chromophore of the blue light photoreceptor cryptochrome in plants?"}],"options":[{"key":"1","text":"B3 and B12"},{"key":"2","text":"B2 and B9"},{"key":"3","text":"B2 and B12"},{"key":"4","text":"B3 and B9"}],"answer":"2","explanation":{"correct":"Cryptochromes bind FAD (from riboflavin, vitamin B2) as the catalytic chromophore and 5,10-methenyltetrahydrofolate (MTHF, from folate, vitamin B9) as the light-harvesting antenna. This architecture is inherited from photolyases (Ahmad &amp; Cashmore 1993, <i>Nature</i> 366:162).","wrong":{"1":"B3 (NAD) and B12 (cobalamin) are not cryptochrome chromophores.","3":"B12 is not involved.","4":"B3 is not involved."}}},{"id":70,"part":"B","unit":9,"blocks":[{"t":"p","h":"Tectonic uplift can alter the drainage patterns of rivers, thereby isolating populations of many species. Population isolation of this kind results from which one of the following processes?"}],"options":[{"key":"1","text":"Dispersal"},{"key":"2","text":"Vicariance"},{"key":"3","text":"Range expansion"},{"key":"4","text":"Competitive exclusion"}],"answer":"2","explanation":{"correct":"Vicariance is the splitting of a once-continuous population by a new geographic barrier (here, river drainages rearranged by uplift), without the organisms moving.","wrong":{"1":"Dispersal is the movement of organisms across an existing barrier.","3":"Range expansion is the opposite of isolation.","4":"Competitive exclusion is a biotic interaction, not geographic isolation."}}},{"id":71,"part":"C","unit":8,"blocks":[{"t":"p","h":"The table below shows types of chemical mutagens and names of mutagens."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X: Types of chemical mutagens","Column Y: Names of mutagens"]],"rows":[["A. Base analogs","i. Nitrous acid"],["B. Intercalating agents","ii. Ethyl Methane Sulphonate"],["C. Deaminating agents","iii. Ethidium Bromide"],["D. Alkylating agents","iv. 5-Bromouracil"]]},{"t":"p","h":"Which one of the following options shows the correct match between Column X and Column Y?"}],"options":[{"key":"1","text":"A: iv B: iii C: i D: ii"},{"key":"2","text":"A: i B: iv C: iii D: ii"},{"key":"3","text":"A: ii B: iii C: iv D: i"},{"key":"4","text":"A: iii B: ii C: i D: iv"}],"answer":"1","explanation":{"correct":"5-Bromouracil is a thymine analogue whose enol (or ionised) form pairs with G, giving transitions. Ethidium bromide intercalates between base pairs and causes frameshifts. Nitrous acid oxidatively deaminates C→U, A→hypoxanthine and G→xanthine. EMS alkylates G at O⁶, and O⁶-ethylG pairs with T (GC→AT transitions).","wrong":{"2":"Nitrous acid is not a base analogue, and 5-BU does not intercalate.","3":"EMS is not a base analogue.","4":"EtBr is not a base analogue, and EMS is not an intercalator."}}},{"id":72,"part":"C","unit":1,"blocks":[{"t":"p","h":"At what range of substrate concentration will an enzyme with a k<sub>cat</sub> of 30 s<sup>−1</sup> and a K<sub>m</sub> of 0.005 M show one-quarter of its maximum rate?"}],"options":[{"key":"1","text":"3.0 × 10<sup>−3</sup> M to 3.1 × 10<sup>−3</sup> M"},{"key":"2","text":"0.65 × 10<sup>−3</sup> M to 0.75 × 10<sup>−3</sup> M"},{"key":"3","text":"1.65 × 10<sup>−3</sup> M to 1.75 × 10<sup>−3</sup> M"},{"key":"4","text":"2.7 × 10<sup>−3</sup> M to 2.8 × 10<sup>−3</sup> M"}],"answer":"3","explanation":{"correct":"From Michaelis–Menten, v/V<sub>max</sub> = [S]/(K<sub>m</sub> + [S]) = 1/4, so 4[S] = K<sub>m</sub> + [S] and [S] = K<sub>m</sub>/3 = 0.005/3 = 1.67 × 10⁻³ M. k<sub>cat</sub> is a distractor: the fraction of V<sub>max</sub> depends only on [S]/K<sub>m</sub>.","wrong":{"1":"≈3 mM gives v ≈ 0.38 V<sub>max</sub>.","2":"≈0.7 mM gives v ≈ 0.12 V<sub>max</sub>.","4":"≈2.75 mM gives v ≈ 0.35 V<sub>max</sub>."}}},{"id":73,"part":"C","unit":1,"blocks":[{"t":"p","h":"A cytoplasmic monomeric protein containing a single non-surface exposed cysteine residue precipitates upon mutation of the Cys to 'Ile'. However, the mutation of Cys to 'Ala' leads to a soluble and functional protein equivalent to the native form. Which one of the following statements explains the above observations?"}],"options":[{"key":"1","text":"Cys mutated to 'Ile' alters the net charge of the protein, while mutation to 'Ala' does not."},{"key":"2","text":"Cys mutated to 'Ala' alters the net charge of the protein, while mutation to 'Ile' does not."},{"key":"3","text":"Cys mutated to 'Ala' causes steric hindrance in the core of the protein, while mutation to 'Ile' does not."},{"key":"4","text":"Cys mutated to 'Ile' causes steric hindrance in the core of the protein, while mutation to 'Ala' does not."}],"answer":"4","explanation":{"correct":"Cys, Ala and Ile are all uncharged, so charge cannot explain the result. The residue is buried, so the protein must accommodate the new side chain in a tightly packed core. Ala (~89 Å³) is smaller than Cys (~109 Å³) and leaves only a small, tolerated cavity. Ile (~167 Å³, β-branched) is much bulkier and clashes with neighbouring residues, destabilising the fold so that the protein misfolds and aggregates.","wrong":{"1":"Ile is neutral; the net charge does not change.","2":"Ala is neutral; the net charge does not change.","3":"Ala is smaller than Cys, so it cannot cause steric clash."}}},{"id":74,"part":"C","unit":2,"blocks":[{"t":"p","h":"Given below are a few statements about intracellular protein transport."},{"t":"p","h":"A. Proteins that are destined for the lysosome are tagged with a mannose-6-phosphate (M6P) group in the Golgi apparatus, which is recognized by the M6P receptor in the trans-Golgi network.<br>B. Signal recognition particle directly mediates the insertion of proteins into the mitochondrial membrane.<br>C. The KDEL receptor in the ER and Golgi apparatus works by retrieving soluble ER resident proteins that have accidentally moved to the Golgi.<br>D. Cargo proteins that need to be exported from the ER are packaged into COPII vesicles based on the presence of an ER export signal in their cytosolic tail.<br>E. Clathrin-coated vesicles are primarily involved in vesicle trafficking between the Golgi apparatus and the ER."},{"t":"p","h":"Choose the option that has all correct statements."}],"options":[{"key":"1","text":"A, C and D"},{"key":"2","text":"A, B and E"},{"key":"3","text":"A and D only"},{"key":"4","text":"C and E"}],"answer":"1","explanation":{"correct":"A is true: GlcNAc-phosphotransferase (cis-Golgi) and uncovering enzyme generate M6P, which binds M6P receptors in the TGN. C is true: KDEL receptors bind escaped KDEL proteins in the Golgi and return them to the ER in COPI vesicles. D is true: transmembrane cargo carries cytosolic export motifs (e.g. diacidic DxE) recognised by the Sec24 subunit of COPII. So A, C and D are correct.","wrong":{"2":"B is false: SRP targets ribosomes to the ER membrane; mitochondrial proteins enter post-translationally via TOM/TIM. E is false (see below).","3":"Omits C, which is true.","4":"E is false: clathrin coats mediate TGN→endosome and plasma-membrane endocytic traffic; Golgi→ER retrograde traffic uses COPI."}}},{"id":75,"part":"C","unit":4,"blocks":[{"t":"p","h":"The following statements are made regarding the role of cadherins in cell junctions."},{"t":"p","h":"A. Cadherins are calcium-dependent adhesion molecules that mediate cell to cell adhesion by forming homophilic interactions.<br>B. Cadherins function in tight junctions, sealing the space between adjacent cells.<br>C. N-cadherins are primarily found in epithelial cells and mediate adhesion to the basal lamina.<br>D. Cadherins are involved in the formation of focal adhesions linking the cell cytoskeleton to the ECM.<br>E. Cadherins interact with the actin cytoskeleton through associated proteins like catenins."},{"t":"p","h":"Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"B, C and E"},{"key":"2","text":"A, B and D"},{"key":"3","text":"A and D only"},{"key":"4","text":"A and E only"}],"answer":"4","explanation":{"correct":"A is true: classical cadherins bind Ca²⁺ between their EC domains and adhere homophilically (strand-swap dimers). E is true: at adherens junctions the cytoplasmic tail binds p120- and β-catenin, and α-catenin links the complex to actin.","wrong":{"1":"B: tight junctions are sealed by claudins and occludin. C: N-cadherin is neural; E-cadherin is epithelial, and adhesion to basal lamina is via integrins.","2":"B and D are false.","3":"D is false: focal adhesions are integrin–ECM junctions."}}},{"id":76,"part":"C","unit":2,"blocks":[{"t":"p","h":"Given below are components that facilitate transfer of molecules across phospholipid bilayers (Column X) and the properties of these components (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X: Membrane component","Column Y: Activity"]],"rows":[["A. ATP powered pumps","I. Movement of molecules against concentration gradient coupled to another molecule moving down the concentration gradient"],["B. Uniporter","II. Free diffusion of hydrophilic molecules"],["C. Channels","III. Movement of molecules against a concentration gradient and/or electric potential"],["D. Symporter","IV. Transport of hydrophilic molecules down their concentration gradients"]]},{"t":"p","h":"Choose the option that correctly matches the components with their properties."}],"options":[{"key":"1","text":"A (IV) B (II) C (I) D (III)"},{"key":"2","text":"A (II) B (III) C (IV) D (I)"},{"key":"3","text":"A (III) B (IV) C (I) D (II)"},{"key":"4","text":"A (III) B (IV) C (II) D (I)"}],"answer":"4","explanation":{"correct":"ATP-powered pumps (P-, V-, F-type, ABC) move solutes uphill against concentration or electrochemical gradients (III). Uniporters carry one solute by facilitated diffusion down its gradient (IV). Channels form aqueous pores that allow fast, free diffusion of specific ions or water (II). Symporters couple uphill transport of one solute to downhill movement of a co-transported ion such as Na⁺ (I).","wrong":{"1":"Pumps are not passive carriers.","2":"Pumps do not allow free diffusion, and uniporters do not pump uphill.","3":"Channels do not perform coupled transport, and symporters are not free-diffusion pores."}}},{"id":77,"part":"C","unit":10,"blocks":[{"t":"p","h":"The following table shows forest floor litter pool and aboveground litterfall data for three forest types."},{"t":"tbl","cls":"","rowHead":false,"head":[["Forest type","Forest floor litter pool (gC/m<sup>2</sup>)","Aboveground litterfall (gC/m<sup>2</sup>/yr)"]],"rows":[["A","5000","50"],["B","1500","300"],["C","600","600"]]},{"t":"p","h":"Based on the provided information, which one of the following options accurately identifies the various forest types?"}],"options":[{"key":"1","text":"A- Tropical forest, B- Temperate deciduous forest, C- Temperate coniferous forest"},{"key":"2","text":"A- Temperate coniferous forest, B- Temperate deciduous forest, C- Tropical forest"},{"key":"3","text":"A- Temperate coniferous forest, B- Tropical forest, C- Temperate deciduous forest"},{"key":"4","text":"A- Tropical forest, B- Temperate coniferous forest, C- Temperate deciduous forest"}],"answer":"2","explanation":{"correct":"At steady state, pool ÷ input gives the mean residence time of litter: A = 5000/50 = 100 yr; B = 1500/300 = 5 yr; C = 600/600 = 1 yr. Decomposition is slowest in cold, acidic, lignin- and resin-rich conifer litter (thick organic horizons), intermediate in temperate deciduous forests, and fastest in warm, humid tropical forests. These also have the highest litterfall and a thin litter layer (Olson 1963, <i>Ecology</i> 44:322).","wrong":{"1":"Tropical forests have the fastest turnover, not the slowest.","3":"Tropical litterfall is the highest of the three, which is C.","4":"Reverses the tropical and coniferous extremes."}}},{"id":78,"part":"C","unit":8,"blocks":[{"t":"p","h":"Quantitative Trait Loci (QTLs) can be identified using two main approaches: bi-parental matings (BPM) and Genome-Wide Association Studies (GWAS). Below are some descriptors related to these strategies:"},{"t":"p","h":"A. Large sample size<br>B. Small sample size<br>C. Population derived from controlled crosses<br>D. Random mating populations<br>E. Limited to two alleles per locus<br>F. Multiple alleles per locus<br>G. Linkage-based mapping<br>H. Linkage disequilibrium-based mapping"},{"t":"p","h":"The table below presents four incomplete statements regarding BPM and GWAS. Each statement can be completed using the above descriptors."},{"t":"tbl","cls":"","rowHead":false,"head":[["Option","Analysis typically conducted on (BPM / GWAS)","Number of alleles that can be analysed (BPM / GWAS)","Analysis relies on (BPM / GWAS)","Sample size needed to identify loci with small effect (BPM / GWAS)"]],"rows":[["i.","C / D","E / F","G / H","A / A"],["ii.","D / C","E / F","H / G","A / B"],["iii.","C / D","F / E","H / G","B / A"],["iv.","D / C","F / E","G / H","B / B"]]},{"t":"p","h":"Which one of the following options correctly completes all statements?"}],"options":[{"key":"1","text":"i"},{"key":"2","text":"ii"},{"key":"3","text":"iii"},{"key":"4","text":"iv"}],"answer":"1","explanation":{"correct":"Bi-parental mapping uses F₂, backcross or RIL populations from a controlled cross (C). Only the two parental alleles segregate (E), and QTLs are located by linkage to markers through recombination in a few meioses (G). GWAS uses diverse, historically random-mating panels (D) that segregate many alleles (F) and relies on population-level linkage disequilibrium built up over many generations (H). In both designs, power to detect small-effect loci rises with sample size, so both need large samples (A, A).","wrong":{"2":"Swaps the populations and the mapping principles.","3":"Swaps allele number and mapping principle, and claims BPM needs small samples.","4":"Swaps the population types and claims small samples suffice."}}},{"id":79,"part":"C","unit":5,"blocks":[{"t":"p","h":"The table below shows different developmental processes and associated signaling molecules/pathways."},{"t":"tbl","cls":"","rowHead":false,"head":[["","Developmental process","Signaling molecules/pathways"]],"rows":[["A","Dorsal/ventral axis specification in amphibian embryo","Wnt/β-catenin; BMP4; Activin/Nodal"],["B","Dorsal/ventral axis specification in mammalian limb","Engrailed; Wnt/β-catenin; BMP"],["C","Dorsal/ventral axis specification in <i>Drosophila</i> oocyte","FGF; Hh; Dpp"],["D","Anterior/posterior axis specification in mammalian limb","Shh; FGF; Notch"]]},{"t":"p","h":"Which one of the following options represents the correct association of developmental processes and signaling molecules?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and D"},{"key":"3","text":"A and C"},{"key":"4","text":"C and D"}],"answer":"1","explanation":{"correct":"A is correct: maternal Wnt/β-catenin on the dorsal side, together with Nodal-related/Activin signals, induces the organizer, while ventral BMP4 specifies ventral fates. B is correct: in the limb, dorsal ectoderm Wnt7a induces Lmx1b in dorsal mesoderm, whereas ventral ectoderm BMP signalling induces Engrailed-1, which represses Wnt7a ventrally.","wrong":{"2":"D is wrong: limb A/P patterning uses Shh from the ZPA with FGFs from the AER and Gli3/Hox genes; Notch is not a principal A/P signal.","3":"C is wrong: oocyte D/V polarity comes from Gurken (a TGF-α/EGF ligand) signalling to Torpedo/EGFR in follicle cells, not FGF/Hh/Dpp.","4":"Both C and D are wrong."}}},{"id":80,"part":"C","unit":3,"blocks":[{"t":"p","h":"The mRNA of the <i>E. coli</i> lac operon contains the open reading frames for <i>lacZ</i>, <i>lacY</i>, and <i>lacA</i> genes from a single cistron. It is observed that <i>lacZ</i> is translated more frequently than <i>lacY</i> or <i>lacA</i>. Which one of the following statements best describes the reason for this observation?"}],"options":[{"key":"1","text":"The Shine-Dalgarno sequence is present upstream of <i>lacZ</i>, but not <i>lacY</i> or <i>lacA</i>, affecting translation initiation rates."},{"key":"2","text":"Inhibitory RNA structures are present upstream of the AUG codon of <i>lacY</i> and <i>lacA</i>, but not <i>lacZ</i>, affecting translation initiation rates."},{"key":"3","text":"Variations in the Shine-Dalgarno sequence upstream of <i>lacZ</i>, <i>lacY</i>, and <i>lacA</i> have different affinities for the ribosome, affecting translation initiation rates."},{"key":"4","text":"Inhibitory RNA structures are present in the <i>lacY</i> and <i>lacA</i> coding sequence but not <i>lacZ</i>, affecting translation elongation rates."}],"answer":"3","explanation":{"correct":"In a polycistronic bacterial mRNA, each ORF has its own ribosome-binding site, and the three are initiated independently. Differences in Shine–Dalgarno complementarity to the 16S rRNA 3′ end (anti-SD) and in spacing to the AUG give different initiation efficiencies. This is why the proteins are made in unequal amounts (roughly Z &gt; Y &gt; A).","wrong":{"1":"Every ORF needs a ribosome-binding site; lacY and lacA have their own SDs.","2":"The key names SD-strength variation, not secondary structure, as the primary cause.","4":"Translation rates in bacteria are controlled mainly at initiation, not elongation."}}},{"id":81,"part":"C","unit":9,"blocks":[{"t":"p","h":"Match the animal in Column X with its characteristic in Column Y."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Snakes","I. Lateral line"],["B. Spiders","II. Heat sensing pits"],["C. Fishes","III. Echolocation"],["D. Dolphins","IV. Spinnerets"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-II B-IV C-I D-III"},{"key":"2","text":"A-I B-II C-III D-IV"},{"key":"3","text":"A-III B-I C-II D-IV"},{"key":"4","text":"A-II B-III C-IV D-I"}],"answer":"1","explanation":{"correct":"Pit vipers, pythons and boas detect infrared with TRPA1-rich pit organs (II). Spiders extrude silk from abdominal spinnerets (IV). Fishes sense water movement with neuromast-based lateral lines (I). Odontocetes such as dolphins echolocate with clicks produced by the phonic lips (III).","wrong":{"2":"Mismatches all four.","3":"Mismatches all four.","4":"Mismatches B, C and D."}}},{"id":82,"part":"C","unit":10,"blocks":[{"t":"p","h":"Which one of the following statements is NOT part of the neutral paradigm in ecology?"}],"options":[{"key":"1","text":"All individuals in the community have equal fitness and competitive ability."},{"key":"2","text":"Loss of competing species to extinction is through a slow, random process."},{"key":"3","text":"Diversity is maintained by speciation rates counteracting extinction rates."},{"key":"4","text":"Ecological drift results in stable coexistence of a given set of species."}],"answer":"4","explanation":{"correct":"In Hubbell's (2001) unified neutral theory, species are ecologically equivalent, so abundances perform a random walk (ecological drift). Drift leads to slow, random extinction, never to stable coexistence. Stability would require stabilising niche differences, which the neutral model explicitly lacks.","wrong":{"1":"This is the core neutrality (per-capita equivalence) assumption.","2":"Under drift, extinction is slow and random.","3":"Diversity at steady state reflects a speciation–extinction (dispersal) balance, as in the fundamental biodiversity number θ."}}},{"id":83,"part":"C","unit":1,"blocks":[{"t":"p","h":"An enzyme has been found to efficiently catalyse the following reaction:"},{"t":"p","h":"A ⇌ B &nbsp;&nbsp; (forward rate constant k<sub>f</sub>, reverse rate constant k<sub>r</sub>); K<sub>eq</sub> = k<sub>f</sub> / k<sub>r</sub>"},{"t":"p","h":"Where k<sub>f</sub>: forward rate of the reaction; k<sub>r</sub>: reverse rate of the reaction; K<sub>eq</sub>: equilibrium constant."},{"t":"p","h":"Which one of the following parameters will be increased over the uncatalyzed reaction by the enzyme?"}],"options":[{"key":"1","text":"k<sub>r</sub>"},{"key":"2","text":"K<sub>eq</sub>"},{"key":"3","text":"1/k<sub>r</sub>"},{"key":"4","text":"1/K<sub>eq</sub>"}],"answer":"1","explanation":{"correct":"A catalyst lowers the activation energy of the transition state shared by both directions. So it increases k<sub>f</sub> and k<sub>r</sub> by the same factor and leaves K<sub>eq</sub> = k<sub>f</sub>/k<sub>r</sub> (and ΔG°) unchanged (principle of microscopic reversibility). Of the listed quantities only k<sub>r</sub> increases.","wrong":{"2":"Enzymes do not change the equilibrium constant.","3":"k<sub>r</sub> increases, so 1/k<sub>r</sub> decreases.","4":"K<sub>eq</sub> is unchanged, so 1/K<sub>eq</sub> is unchanged."}}},{"id":84,"part":"C","unit":6,"blocks":[{"t":"p","h":"The figure below depicts the feedback regulation in the biosynthesis pathway of three branched-chain amino acids (BCAA) - Leu, Val, and Ile, acting at three major steps catalyzed by enzymes AHAS, IPMS, and TD. The activity of AHAS is feedback regulated by the synergistic combination of Leu and Val. IPMS activity is regulated exclusively by Leu. Ile regulates TD activity while Val can relax this feedback regulation on TD by Ile."},{"t":"img","src":"data:image/webp;base64,","w":470,"h":320,"alt":"Pathway: pyruvate via AHAS to 2-oxoisovalerate, which branches to Val and, via IPMS, to Leu; threonine via TD to Ile. Leu feeds back on IPMS and with Val on AHAS; Ile inhibits TD and Val relieves that inhibition"},{"t":"p","h":"Which one of the following possibilities of BCAA pools is likely to occur in the RNAi knockdown of IPMS?"}],"options":[{"key":"1","text":"Both Leu and Val will decrease."},{"key":"2","text":"Leu will decrease, and Val remains unchanged."},{"key":"3","text":"Leu will decrease and both Val and Ile will increase."},{"key":"4","text":"Only Leu will decrease."}],"answer":"3","explanation":{"correct":"Knocking down IPMS cuts the Leu branch, so Leu falls. Two consequences follow. (i) 2-Oxoisovalerate is diverted into the Val branch, so Val rises. (ii) AHAS needs Leu <i>plus</i> Val for synergistic feedback inhibition; with Leu low, AHAS is de-repressed. AHAS also makes 2-aceto-2-hydroxybutyrate (the Ile precursor) from 2-oxobutyrate, and the higher Val relaxes Ile's inhibition of TD. Both effects raise flux into Ile. Net: Leu ↓, Val ↑, Ile ↑.","wrong":{"1":"Val rises, not falls, because precursor is diverted to it.","2":"Val does not stay unchanged; it is diverted and AHAS is de-repressed.","4":"Val and Ile also change."}}},{"id":85,"part":"C","unit":4,"blocks":[{"t":"p","h":"The following statements are made regarding apoptosis in the nematode, <i>C. elegans</i>:"},{"t":"p","h":"A. The human ortholog of <i>C. elegans</i> CED-9 is overexpressed in a B-cell lymphoma.<br>B. A <i>ced-9(gain-of-function); ced-3(loss-of-function)</i> double mutant will have more than 947 non-gonadal cells.<br>C. If purified EGL-1 is added to a CED-9/CED-4 complex <i>in vitro</i>, the autocleavage of CED-3 does not occur.<br>D. CED-8 is a multi-spanning plasma membrane protein that is required for externalization of phosphatidylserine."},{"t":"p","h":"Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A, B, C and D"},{"key":"2","text":"A and B only"},{"key":"3","text":"A, B and D only"},{"key":"4","text":"B, C and D only"}],"answer":"3","explanation":{"correct":"A is true: the CED-9 ortholog BCL-2 is overexpressed by the t(14;18) translocation in follicular B-cell lymphoma; human BCL-2 can even substitute for CED-9 in worms (Vaux, Weissman &amp; Kim 1992, <i>Science</i> 258:1955). B is true: both mutations block the core death pathway, so the cells that normally die (~131 in the hermaphrodite) survive and the somatic cell count exceeds wild type. D is true: CED-8, an Xk-family multi-pass membrane protein, promotes phosphatidylserine exposure on apoptotic cells (Suzuki et al. 2013, <i>Science</i> 341:403).","wrong":{"1":"C is false: EGL-1 binding to CED-9 displaces CED-4 (Yan et al. 2005, <i>Nature</i> 437:831), freeing CED-4 to oligomerise into the apoptosome and drive CED-3 autoactivation.","2":"Omits D, which is true.","4":"Includes C and omits A."}}},{"id":86,"part":"C","unit":9,"blocks":[{"t":"p","h":"The following statements describe change in allele frequencies over time."},{"t":"p","h":"A. Fixation of an allele is purely by chance, while other alleles are lost.<br>B. Genetic drift can lead to the loss of certain alleles over time, reducing genetic diversity within the population.<br>C. Changes in allele frequencies are due to positive selection.<br>D. There is a pronounced effect in small populations, where random events can drastically alter allele frequencies."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements if allele frequencies change purely due to genetic drift?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"A, B and D"},{"key":"3","text":"B, C and D"},{"key":"4","text":"A, C and D"}],"answer":"2","explanation":{"correct":"Under pure drift, which allele fixes is random: a neutral allele's fixation probability equals its current frequency (A). Heterozygosity decays as H<sub>t</sub> = H<sub>0</sub>(1 − 1/2N)<sup>t</sup> (B). The variance of the change in allele frequency per generation is p(1−p)/2N, so the effect is strongest in small populations (D).","wrong":{"1":"C invokes selection, which is excluded by \"purely due to genetic drift\".","3":"C is false under pure drift.","4":"C is false under pure drift."}}},{"id":87,"part":"C","unit":14,"blocks":[{"t":"p","h":"The figure given below represents the same data in six different ways. \"A\" represents the scatter plot of all data points and \"B\" is its corresponding box and whisker plot. \"C\" to \"F\" represent the same dataset with different measures of central tendency alongside various measures of variation (SEM - Standard Error of Mean, SD - Standard Deviation, CI - 95% confidence interval)."},{"t":"img","src":"data:image/webp;base64,","w":435,"h":265,"alt":"Panels A to F of one dataset: A scatter of about 20 points from 5 to 21; B box plot with median 10; C point at 10 with bars about 7.5 to 14; D point at 11 with the widest bars, about 6.5 to 15.5; E point at 11 with bars about 9 to 13; F point at 11 with the narrowest bars, about 10 to 12"},{"t":"p","h":"Which one of the following options is a correct representation of the data?"}],"options":[{"key":"1","text":"C = Mean ± quartiles; D = Median ± SEM; E = Median ± CI"},{"key":"2","text":"D = Mean ± SD; E = Mean ± CI; F = Mean ± SEM"},{"key":"3","text":"C = Median with quartiles; D = Mean ± SEM; E = Mean with CI"},{"key":"4","text":"D = Mean ± SEM; E = Mean ± CI; F = Mean ± SD"}],"answer":"2","explanation":{"correct":"C sits at 10, the median shown in the box plot, with bars matching the box (interquartile range), so C is the median with quartiles. D, E and F share a centre of ~11 (the mean, pulled up by the right-skewed high values). For <i>n</i> ≈ 20, SEM = SD/√<i>n</i> ≈ SD/4.5 and the 95% CI ≈ mean ± 2.1·SEM ≈ ± 0.47·SD. So the widest bar is SD (D), the intermediate one is the CI (E) and the narrowest is SEM (F).","wrong":{"1":"C's centre is the median (10), not the mean, and D, E and F are centred on the mean.","3":"C is right, but D (the widest bar) cannot be the SEM.","4":"SD bars must be the widest, not the narrowest."}}},{"id":88,"part":"C","unit":5,"blocks":[{"t":"p","h":"The following statements were made regarding regulation of aging in <i>C. elegans</i>:"},{"t":"p","h":"A. In most cells, p53 remains bound to a repressor protein to keep it inactive, which is activated under oxidative stress when DNA damage separates p53 from its repressor.<br>B. DAF-2 functions as an insulin-like growth factor receptor to block Forkhead transcription factor and increases the life span.<br>C. When DAF-2 is not active, cells reduce the production of DNA repair enzymes.<br>D. Dietary restriction increases mTORC1 activity, enhancing functional stem cells and longevity."},{"t":"p","h":"Which one of the following options has the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"1","explanation":{"correct":"NTA's key is A and B. A is true: p53 (CEP-1 in worms) is held inactive by a repressor (MDM2 in mammals) and released by stress-induced post-translational modification. B is the textbook description of the insulin/IGF-1 pathway: DAF-2 signalling, via AGE-1/PI3K and AKT, phosphorylates and excludes the FOXO factor DAF-16 from the nucleus. Read in the key's sense, blocking this DAF-2 → DAF-16 inhibition extends lifespan; <i>daf-2</i> mutants live about twice as long (Kenyon et al. 1993, <i>Nature</i> 366:461).","wrong":{"2":"C is false: with DAF-2 inactive, nuclear DAF-16 <i>up-regulates</i> stress-resistance and repair genes (SOD-3, catalases, small HSPs).","3":"C and D are false.","4":"D is false: dietary restriction <i>reduces</i> TOR signalling, and TOR inhibition extends lifespan."},"notes":["Strictly worded, B is imprecise: active DAF-2 shortens lifespan, and its <i>loss</i> extends it. Choose A and B because C and D are unambiguously false."]}},{"id":89,"part":"C","unit":4,"blocks":[{"t":"p","h":"In an experiment, FITC-CD4 and PE-CD8 were used to stain thymocytes. The cells were then run through a flow cytometer and the data were plotted as CD4 vs CD8. The results are shown in the figure below and following statements are made:"},{"t":"img","src":"data:image/webp;base64,","w":270,"h":275,"alt":"Flow cytometry plot of thymocytes, CD4 versus CD8: CD4 single positive 7.06%, double positive 87.5%, double negative 3.58%, CD8 single positive 1.86%"},{"t":"p","h":"A. Rearrangement of TCR-β locus is initiated in cells included in the quadrant containing 3.58% of the population.<br>B. TCR-α locus rearrangement occurs in cells included in the quadrant containing 87.5% population.<br>C. FITC-CD4 and PE-CD8 cannot stain the same cells.<br>D. Rearranged TCR-γδ receptor is expressed on 7.06% population of cells."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"B only"}],"answer":"1","explanation":{"correct":"A is true: the 3.58% quadrant is CD4⁻CD8⁻ (double negative). TCRβ (and γ/δ) rearrangement starts at the DN2–DN3 stage, and β-selection drives progression. B is true: the 87.5% quadrant is CD4⁺CD8⁺ (double positive), where RAG is re-expressed and TCRα rearranges (with repeated attempts) before positive selection.","wrong":{"2":"D is false: the 7.06% quadrant is CD4 single positive (αβ T cells); most γδ T cells are CD4⁻CD8⁻.","3":"C is false: the DP cells (87.5%) are stained by both antibodies at once.","4":"Omits A, which is true."}}},{"id":90,"part":"C","unit":7,"blocks":[{"t":"p","h":"Men suffering from enlarged prostate disease were prescribed drugs that would specifically target the androgen receptor (AR). While developing the drug, the following considerations were deliberated on:"},{"t":"p","h":"A. Drugs should target the N-terminal domain of the AR.<br>B. Drugs should not target the NLS domain of the AR.<br>C. The drug should bind to the ligand-binding domain of the AR.<br>D. The drug should activate CYP17A1 to facilitate conversion of pregnenolone to DHEA."},{"t":"p","h":"Which one of the following combinations of considerations will develop the best drug for treatment of enlarged prostate?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and C"}],"answer":"4","explanation":{"correct":"Two validated ways to block AR exist. (C) Ligand-binding-domain antagonists compete with DHT; examples are flutamide, bicalutamide and enzalutamide (the latter also impairs nuclear translocation and DNA binding). (A) N-terminal-domain inhibitors (e.g. EPI-001 or ralaniten) block the AF-1 transactivation function, which carries most AR activity and remains active in LBD-truncated splice variants such as AR-V7.","wrong":{"1":"B is wrong: blocking nuclear import (the NLS/hinge) is a legitimate way to inhibit AR, so there is no reason to avoid it.","2":"B is wrong (see option 1).","3":"D is counterproductive: CYP17A1 drives androgen synthesis, and therapy <i>inhibits</i> it (abiraterone)."}}},{"id":91,"part":"C","unit":3,"blocks":[{"t":"p","h":"The helicase activity of <i>E. coli</i> DnaB was investigated using the following two substrates (I and II) under various conditions, followed by gel electrophoresis and autoradiography. The results of these experiments are depicted below:"},{"t":"img","src":"data:image/webp;base64,","w":595,"h":285,"alt":"Autoradiograph. Substrate I (fully duplex, one strand radiolabelled): lane with SSB, DnaB and ATP stays duplex; boiled lane gives single strand; untreated lane duplex. Substrate II (forked duplex with single-stranded 5' and 3' tails): SSB+DnaB+ATP gives single strand; SSB+DnaB without ATP stays mostly duplex; SSB+ATP without DnaB gives faint duplex and faint single strand; boiled gives single strand; untreated duplex"},{"t":"p","h":"The following statements are made purely from the results shown above:"},{"t":"p","h":"A. DnaB can unwind only a partially unwound DNA.<br>B. SSB inhibits the unwinding activity of DnaB.<br>C. DnaB unwinds DNA in the 5′ to 3′ direction.<br>D. DnaB requires ATP for DNA unwinding."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and D"},{"key":"2","text":"A, C and D"},{"key":"3","text":"C and D only"},{"key":"4","text":"A and D only"}],"answer":"4","explanation":{"correct":"A is supported: the fully duplex, blunt substrate I is not unwound even with SSB, DnaB and ATP, whereas forked substrate II is fully converted to single strands. DnaB needs a single-stranded loading region. D is supported: on substrate II, omitting ATP leaves the duplex intact.","wrong":{"1":"B is not supported: SSB is present in the lane where unwinding is complete.","2":"C cannot be inferred: substrate II has both 5′ and 3′ single-stranded tails, so polarity cannot be told apart. (DnaB is in fact a 5′→3′ helicase, but that is not shown by this data.)","3":"C is not shown, and A is omitted."}}},{"id":92,"part":"C","unit":9,"blocks":[{"t":"p","h":"Two closely related sympatric ladybird beetle species in a rainforest have evolved to specialise on different insect prey. Which one of the following statements does NOT explain the speciation process in these beetle species?"}],"options":[{"key":"1","text":"Populations exploited different diets in the rainforests."},{"key":"2","text":"Over time, natural selection favoured traits that allowed the consumption of distinct diets."},{"key":"3","text":"Diverging populations developed differences in diet. However, it did not lead to reproductive isolation."},{"key":"4","text":"Temporal differentiation in their foraging activity led to their distinct diets."}],"answer":"3","explanation":{"correct":"Speciation requires reproductive isolation. Ecological divergence in diet that does <i>not</i> produce reproductive isolation leaves a single interbreeding species with polymorphic feeding, so it cannot explain the origin of two species.","wrong":{"1":"Divergent resource use is the starting point of ecological (sympatric) speciation.","2":"Divergent natural selection on feeding traits is the mechanism of ecological speciation.","4":"Temporal (allochronic) differentiation can both separate diets and reduce encounters between populations, contributing to isolation."}}},{"id":93,"part":"C","unit":8,"blocks":[{"t":"p","h":"Given below are a few statements regarding gene actions observed in plants."},{"t":"p","h":"A. In terms of pollination, self-pollinated species often exhibit additive gene action.<br>B. Non-additive gene action is less prevalent in cross-pollinated species.<br>C. Simply inherited (qualitative, oligogenic) traits predominantly exhibit non-additive and epistatic gene action.<br>D. Genetic fixation of superior genes will be more difficult with dominance gene action."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"A, C and D"},{"key":"3","text":"B, C and D"},{"key":"4","text":"A and B only"}],"answer":"2","explanation":{"correct":"A is true: inbreeding fixes homozygotes, so the exploitable variance in self-pollinated crops is mainly additive (and additive × additive), which suits pure-line and pedigree selection. C is true: oligogenic qualitative traits usually show complete dominance and classical epistatic ratios, i.e. non-additive action. D is true: dominance (and overdominance) effects come from heterozygote interactions that break down on selfing, so they cannot be fixed in a true-breeding line; only additive effects can.","wrong":{"1":"B is false: cross-pollinated species retain heterozygosity, and non-additive (dominance) variance is more prevalent. This is the basis of heterosis and hybrid breeding in maize.","3":"B is false.","4":"B is false, and C and D are omitted."}}},{"id":94,"part":"C","unit":6,"blocks":[{"t":"p","h":"The table given below provides a comprehensive list of selected plant diseases (Column X) and possible causal pathogens (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X: Plant disease","Column Y: Pathogen"]],"rows":[["A. Apple scab","I. <i>Claviceps purpurea</i>"],["B. Ergot of cereals","II. <i>Erwinia amylovora</i>"],["C. Fire blight","III. <i>Meloidogyne</i> spp."],["D. Root-Knot","IV. <i>Venturia inaequalis</i>"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-IV B-II C-III D-I"},{"key":"2","text":"A-II B-I C-IV D-III"},{"key":"3","text":"A-I B-IV C-III D-II"},{"key":"4","text":"A-IV B-I C-II D-III"}],"answer":"4","explanation":{"correct":"Apple scab is caused by the ascomycete <i>Venturia inaequalis</i> (IV). Ergot is caused by <i>Claviceps purpurea</i>, whose sclerotia replace grains (I). Fire blight of apple and pear is caused by the bacterium <i>Erwinia amylovora</i> (II). Root-knot is caused by the nematode <i>Meloidogyne</i> spp., which forms giant cells and galls (III).","wrong":{"1":"Matches ergot with <i>Erwinia</i> and root-knot with <i>Claviceps</i>.","2":"Matches scab with <i>Erwinia</i>.","3":"Matches scab with <i>Claviceps</i>."}}},{"id":95,"part":"C","unit":6,"blocks":[{"t":"p","h":"A researcher obtained a loss-of-function mutant of plasmodesmata protein synaptotagmin (SYTA) in Arabidopsis and infected the plants with cabbage leaf curl virus (CaLCuV). The following statements represent possible outcomes of the above experiment."},{"t":"p","h":"A. The CaLCuV infection will be slower in the mutant plants.<br>B. The mutant plants will be completely resistant to the viral infection.<br>C. The endocytic recycling pathway in the infected cells will be compromised in the mutant plants.<br>D. The disease symptoms will be more severe in the mutant plants."},{"t":"p","h":"Which one of the following options represents all correct statement(s)?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and C"},{"key":"3","text":"B only"},{"key":"4","text":"D"}],"answer":"1","explanation":{"correct":"SYTA localises to plasma-membrane–derived endosomes at plasmodesmata. It regulates endocytic recycling and binds viral movement proteins, including CaLCuV BC1. In the <i>syta-1</i> mutant, endocytic recycling is impaired and the systemic spread of CaLCuV is <b>delayed</b> (Lewis &amp; Lazarowitz 2010, <i>PNAS</i> 107:2491).","wrong":{"2":"B is false: infection is delayed, not abolished.","3":"B is false.","4":"D is false: slower movement delays, rather than worsens, symptoms."}}},{"id":96,"part":"C","unit":1,"blocks":[{"t":"p","h":"If a 0.1 M solution of glucose 1-phosphate is incubated with a catalytic amount of phosphoglucomutase, the glucose 1-phosphate is transformed to glucose 6-phosphate. At equilibrium, the concentrations of the reaction components are:"},{"t":"p","h":"Glucose 1-phosphate (4.5 × 10<sup>−3</sup> M) ⇌ Glucose 6-phosphate (9.6 × 10<sup>−2</sup> M)"},{"t":"p","h":"What would be the calculated values for K′<sub>eq</sub> and ΔG°′ for this reaction at 25°C?"}],"options":[{"key":"1","text":"(0.0045 to 0.096) and (−0.7 to −0.8) kJ/mol"},{"key":"2","text":"(21 to 22) and (−7.5 to −7.7) kJ/mol"},{"key":"3","text":"(0.1 to 0.2) and (−17.6 to −17.7) kJ/mol"},{"key":"4","text":"(21 to 22) and (−27.7 to −27.8) kJ/mol"}],"answer":"2","explanation":{"correct":"K′<sub>eq</sub> = [G6P]/[G1P] = 0.096/0.0045 = 21.3. ΔG°′ = −RT ln K′<sub>eq</sub> = −(8.315 × 10⁻³ kJ mol⁻¹ K⁻¹)(298 K)(ln 21.3 = 3.06) = −7.6 kJ/mol. This is Lehninger's worked example; the textbook value is −7.3 kJ/mol.","wrong":{"1":"Uses the concentrations themselves rather than their ratio.","3":"Inverts or misuses the ratio.","4":"The right K′<sub>eq</sub> but a ΔG°′ off by a factor of about 3.6 (e.g. using log₁₀ wrongly, or wrong units)."}}},{"id":97,"part":"C","unit":14,"blocks":[{"t":"p","h":"A purified 150 kDa protein species from gel filtration column was run on a 2-dimensional SDS-PAGE as shown below:"},{"t":"img","src":"data:image/webp;base64,","w":235,"h":140,"alt":"Two-dimensional gel: first dimension SDS-PAGE (non-reducing, left to right), second dimension SDS-PAGE with DTT (top to bottom); two spots lie one above the other at the same first-dimension position"},{"t":"p","h":"What is the likely form of the 150 kDa protein species from this observation?"}],"options":[{"key":"1","text":"There are at least two proteins that are linked through non-covalent interactions."},{"key":"2","text":"There are at least two proteins in the complex that are linked through covalent bonds."},{"key":"3","text":"There are two proteins in the mixture without forming a complex."},{"key":"4","text":"There is only one protein that has a disulfide bond."}],"answer":"2","accept":["2","4"],"explanation":{"correct":"This is a diagonal (non-reducing → reducing) gel. In the first dimension, without DTT, SDS already disrupts non-covalent interactions, so the 150 kDa species runs as a single disulfide-intact unit. Reduction before the second dimension breaks S–S bonds. Two spots that share one first-dimension position but separate in the second show that the 150 kDa species consists of at least two different polypeptides joined by interchain disulfide bonds (as in IgG heavy and light chains).","wrong":{"1":"Non-covalent partners would already separate in the first (SDS) dimension.","3":"Unlinked proteins would separate in the first dimension and lie on the diagonal."},"notes":["NTA's final key accepts option 2 <b>or</b> option 4: either answer earns full marks. Option 2 is the interpretation that fits two spots in one first-dimension column. A single chain with an intrachain disulfide would give one spot shifted slightly off the diagonal."]}},{"id":98,"part":"C","unit":3,"blocks":[{"t":"p","h":"Given below are different types of genetic manipulations of <i>E. coli trp</i> operon (Column X) and their consequences on its transcription (Column Y) under high tryptophan concentration."},{"t":"img","src":"data:image/webp;base64,","w":585,"h":130,"alt":"trp operon map: trpR, promoter P, operator O, leader trpL containing sequences 1, 2, 3 and 4 with the attenuator, followed by trpE, trpD, trpC, trpB and trpA"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Inserting bases between the leader peptide gene and sequence 2","i. Complete attenuation"],["B. Inserting bases between sequences 2 and 3","ii. Less attenuation"],["C. Deleting sequence 4","iii. More attenuation"],["D. Elimination of ribosome-binding site for the leader peptide","iv. No attenuation"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A (i) B (ii) C (iii) D (iv)"},{"key":"2","text":"A (i) B (iii) C (ii) D (iv)"},{"key":"3","text":"A (iv) B (ii) C (iii) D (i)"},{"key":"4","text":"A (ii) B (iii) C (iv) D (i)"}],"answer":"4","explanation":{"correct":"At high Trp, the ribosome translates the leader peptide (whose Trp codons lie in region 1) and stops at its stop codon, covering regions 1–2. Region 3 then pairs with 4 to form the terminator (attenuation). (A) Spacing the leader ORF further from region 2 means the terminating ribosome no longer covers region 2, so 2:3 (antiterminator) can form part of the time: <b>less</b> attenuation (ii). (B) Lengthening the 2–3 spacer weakens 2:3 pairing and favours 3:4: <b>more</b> attenuation (iii). (C) Without region 4 no terminator can form: <b>no</b> attenuation (iv). (D) With no leader translation, 1:2 and then 3:4 form by default, terminating transcription constitutively: <b>complete</b> attenuation (i) (Yanofsky 1981, <i>Nature</i> 289:751).","wrong":{"1":"Reverses the consequences of C and D.","2":"Deleting the terminator half cannot increase attenuation.","3":"An untranslated leader gives termination, not read-through."}}},{"id":99,"part":"C","unit":4,"blocks":[{"t":"p","h":"Lethally irradiated mice were split into 4 groups and experiments were conducted as described below:"},{"t":"p","h":"Group 1 was not given any cells.<br>Group 2 was given thymus-derived cells from a syngeneic donor, and two months later, immunized with a polysaccharide antigen.<br>Group 3 was given bone marrow cells from a syngeneic donor, and two months later, immunized with a polysaccharide antigen.<br>Group 4 was given bone marrow cells from a syngeneic donor, and two months later, immunized with a T-dependent antigen."},{"t":"p","h":"Four possible outcomes, listed below, were suggested."},{"t":"p","h":"A. Group 1 mice are unlikely to survive.<br>B. Group 2 mice are likely to produce antibodies in response to polysaccharide antigens.<br>C. Group 3 mice are likely to produce antibodies in response to polysaccharide antigens.<br>D. Group 4 mice are likely to produce antibodies in response to T-dependent antigens."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A, B and D"},{"key":"3","text":"A and C only"},{"key":"4","text":"A, C and D"}],"answer":"4","explanation":{"correct":"A is true: lethal irradiation ablates haematopoiesis, so untreated mice die of marrow failure. C is true: syngeneic bone marrow contains HSCs that rebuild all lineages within ~2 months, including B cells (which respond to T-independent polysaccharide antigens). D is true: the same reconstitution includes T cells matured in the host thymus, whose radioresistant stroma survives, so T-dependent responses are restored too.","wrong":{"1":"B is false: thymocytes and T cells contain no B cells or stem cells, so no antibody can be made (and the mice lack haematopoiesis).","2":"B is false.","3":"Omits D, which is true."}}},{"id":100,"part":"C","unit":10,"blocks":[{"t":"p","h":"Which statement about studies on succession is INCORRECT?"}],"options":[{"key":"1","text":"Succession studies can reveal the effects of non-native species on the ecological structures and functions of a community."},{"key":"2","text":"Studies of succession can indicate threshold conditions for the 'invasion window'."},{"key":"3","text":"Non-native invasion can divert succession by out-competing existing species."},{"key":"4","text":"Succession studies show that coevolved native species always outcompete invasive species."}],"answer":"4","explanation":{"correct":"Many invaders (e.g. <i>Lantana camara</i> and <i>Chromolaena odorata</i> in Indian forests, cheatgrass in North America) out-compete natives and arrest or deflect succession. Co-evolution with the community gives natives no guarantee of competitive superiority, so \"always\" is false.","wrong":{"1":"Correct: chronosequence and long-term plot studies document invader impacts.","2":"Correct: disturbance and resource pulses open \"invasion windows\" that succession studies can identify.","3":"Correct: invaders can create alternative successional trajectories."}}},{"id":101,"part":"C","unit":14,"blocks":[{"t":"p","h":"Two newly identified proteins, X and Y, are tested for sequence-specific DNA binding activity. The results of an electrophoretic mobility shift assay (EMSA) with a labeled DNA fragment and proteins X and Y in various combinations are shown below."},{"t":"img","src":"data:image/webp;base64,","w":350,"h":355,"alt":"EMSA. Lanes: 1 DNA only (free DNA); 2 DNA + X (shifted band); 3 DNA + Y (shifted band slightly lower); 4 DNA + X + Y (two shifted bands plus a higher supershifted band); 5 DNA + X + poly dI:dC (free DNA only); 6 DNA + Y + poly dI:dC (shifted band retained)"},{"t":"p","h":"Poly dI:dC is a DNA duplex of polyinosine and polycytosine. Which one of the following options represents the correct interpretation of the results obtained?"}],"options":[{"key":"1","text":"Both X and Y are sequence-specific DNA binding proteins."},{"key":"2","text":"X does not bind to DNA and Y binds to specific sequence."},{"key":"3","text":"Both proteins bind to DNA but Y binds in a sequence-specific manner."},{"key":"4","text":"X competes with Y to bind the same sequence."}],"answer":"3","explanation":{"correct":"Both proteins shift the probe on their own (lanes 2 and 3), so both bind DNA. Poly dI:dC is a non-specific competitor: it soaks up proteins that bind any DNA, but not those that recognise a specific sequence. The X shift disappears with poly dI:dC (lane 5), so X binds non-specifically. The Y shift persists (lane 6), so Y binds a specific sequence.","wrong":{"1":"X loses binding with poly dI:dC, so it is not sequence-specific.","2":"X clearly shifts the probe in lane 2.","4":"With both proteins a slower ternary complex appears (lane 4): they can bind together, not competitively."}}},{"id":102,"part":"C","unit":10,"blocks":[{"t":"p","h":"The following statements are about parental care and variance in reproductive success in a bird species."},{"t":"p","h":"A. If females provide more parental care than males, the variance in male reproductive success is significantly greater than that of females.<br>B. Where only males provide parental care, the variance in female reproductive success is significantly higher than that of males.<br>C. In the case of biparental care, the variance in male reproductive success is significantly greater than that of females.<br>D. In the case of biparental care, the variance in female reproductive success is significantly greater than that of males."},{"t":"p","h":"Select the option that identifies the combination of all correct statements."}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A and C"},{"key":"3","text":"B and D"},{"key":"4","text":"C and D"}],"answer":"1","explanation":{"correct":"Under Trivers' (1972) parental-investment theory, the sex that invests less competes for the sex that invests more and so shows the higher variance in reproductive success (Bateman's principle). A is true: with female-biased care, male RS variance is greater. B is true: with male-only care (sex-role reversal, e.g. jacanas and phalaropes), females compete and have the higher variance.","wrong":{"2":"C is false: with roughly equal biparental care, neither sex shows significantly greater variance (most socially monogamous birds).","3":"D is false for the same reason.","4":"Both C and D are false."}}},{"id":103,"part":"C","unit":14,"blocks":[{"t":"p","h":"A student used four 20-mer oligos to amplify DNA (using a regular Taq DNA polymerase) from a wild type (WT), a homozygous mutant having a deletion of the gene (del), and from the heterozygous mutant (het), as shown in the figure below."},{"t":"img","src":"data:image/webp;base64,","w":365,"h":162,"alt":"Map: primer FW and, 500 bp downstream of it, primer FD point right towards a 15 kb deletion; primer D points left from 500 bp inside the deleted region; primer R points left 300 bp beyond the right end of the deletion"},{"t":"p","h":"Agarose gel electrophoresis profiles, using all four primers simultaneously, on each template are shown below. Which one of the options given below represents the correct profile?"},{"t":"img","src":"data:image/webp;base64,","w":195,"h":395,"alt":"Four gel options with lanes WT, het, del and markers 1000, 750 and 500 bp. 1: WT 1000+500, het 1000+750+500, del 750+500. 2: WT 1000+500, het 1000+750+500, del 750 only. 3: WT two bands near 1000 plus 500, het same plus 750, del about 1000 and 750. 4: WT 1000+500, het 1000+750+two bands near 500, del 750+500"}],"options":[{"key":"1","text":"Profile 1"},{"key":"2","text":"Profile 2"},{"key":"3","text":"Profile 3"},{"key":"4","text":"Profile 4"}],"answer":"2","explanation":{"correct":"Taq cannot amplify across the intact 15 kb in a standard PCR, so in WT only primer pairs that use D (inside the deleted region) give products: a larger FW–D band (~1000 bp) and a smaller FD–D band (~500 bp). In the homozygous deletion the D site is gone, so neither of those bands can form. Instead, closing the 15 kb gap brings R within range of the upstream primers, giving the deletion-junction band (~750 bp) only. The heterozygote carries both alleles and shows the sum: 1000 + 750 + 500. Only Profile 2 fits.","wrong":{"1":"The del lane cannot show a D-dependent 500 bp band; primer D's site is deleted.","3":"The del lane cannot contain the ~1000 bp FW–D product, and WT shows an extra band.","4":"The del lane shows a ~500 bp band, which requires primer D."}}},{"id":104,"part":"C","unit":10,"blocks":[{"t":"p","h":"The table below lists selected bird species (Column X) and their possible habitats (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Bugun liocichla (<i>Liocichla bugunorum</i>)","I. High altitude Western Himalayas"],["B. Grey-headed Bulbul (<i>Pycnonotus priocephalus</i>)","II. Northeast India"],["C. Brooks's Leaf-Warbler (<i>Phylloscopus subviridis</i>)","III. Western Ghats"],["","IV. Andaman and Nicobar Islands"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-I B-II C-III"},{"key":"2","text":"A-III B-I C-IV"},{"key":"3","text":"A-IV B-II C-III"},{"key":"4","text":"A-II B-III C-I"}],"answer":"4","explanation":{"correct":"The Bugun liocichla was described in 2006 from Eaglenest Wildlife Sanctuary, Arunachal Pradesh, in Northeast India (II). The Grey-headed bulbul is a Western Ghats endemic of wet evergreen forest (III). Brooks's leaf warbler breeds in the high-altitude coniferous forests of the north-western (Western) Himalaya (I).","wrong":{"1":"Mismatches all three.","2":"Mismatches all three.","3":"Places the liocichla on the Andamans."}}},{"id":105,"part":"C","unit":6,"blocks":[{"t":"p","h":"Shown in the table below are the enzymes (Column X) involved in the biosynthesis of listed phytohormones (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Carotenoid cleavage dioxygenase","i. Brassinosteroid"],["B. ER localized cytochrome P450 monooxygenase","ii. Strigolactone"],["C. ACC oxidase","iii. Abscisic acid"],["D. 9-<i>cis</i>-epoxycarotenoid dioxygenase","iv. Ethylene"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A (ii) B (i) C (iii) D (iv)"},{"key":"2","text":"A (i) B (ii) C (iv) D (iii)"},{"key":"3","text":"A (iv) B (ii) C (iii) D (i)"},{"key":"4","text":"A (ii) B (i) C (iv) D (iii)"}],"answer":"4","explanation":{"correct":"CCD7 and CCD8 cleave β-carotene en route to carlactone, the strigolactone precursor (ii). ER-bound P450s (DWF4/CYP90B1, CPD/CYP90A1, BR6ox/CYP85A) catalyse most brassinosteroid oxidations (i). ACC oxidase converts ACC to ethylene (iv). NCED cleaves 9-<i>cis</i>-violaxanthin or neoxanthin to xanthoxin, the rate-limiting step of ABA synthesis (iii).","wrong":{"1":"Swaps ACC oxidase (ethylene) and NCED (ABA).","2":"Swaps CCD and P450.","3":"Mismatches all four."}}},{"id":106,"part":"C","unit":1,"blocks":[{"t":"p","h":"Three strands of a beta-sheet of 4 peptides are hydrogen bonded with the orientation of the strands (parallel or antiparallel denoted by the arrowheads) as shown in the figure. Each strand consists of identical residues, where N and C represent terminal residues of the peptide. The three strands of each peptide are linked by amino acid sequences of the smallest length possible."},{"t":"img","src":"data:image/webp;base64,","w":590,"h":175,"alt":"Four three-stranded sheets. Peptide 1: down, up, down (all antiparallel). Peptide 2: down, down, down (all parallel). Peptide 3: down, down, up (parallel pair then antiparallel). Peptide 4: down, up, up (antiparallel pair then parallel)"},{"t":"p","h":"Which one of the following options is correct regarding the length of the peptides 1 to 4?"}],"options":[{"key":"1","text":"(Peptide 1 = Peptide 2) &lt; Peptide 3 &lt; Peptide 4"},{"key":"2","text":"Peptide 1 &lt; (Peptide 3 = Peptide 4) &lt; Peptide 2"},{"key":"3","text":"Peptide 1 &lt; Peptide 3 &lt; Peptide 4 &lt; Peptide 2"},{"key":"4","text":"Peptide 1 &lt; Peptide 2 &lt; Peptide 3 &lt; Peptide 4"}],"answer":"2","explanation":{"correct":"Adjacent antiparallel strands can be joined by a tight β-hairpin (a 2–5-residue turn). Adjacent parallel strands end and start at opposite edges of the sheet, so the connection must cross from one end of the sheet to the other: a crossover connection, typically a long loop or a β-α-β unit. The strands are identical, so length depends only on the connections. Peptide 1 has 2 hairpins (shortest). Peptides 3 and 4 each have 1 hairpin + 1 crossover (equal). Peptide 2 has 2 crossovers (longest).","wrong":{"1":"Peptide 2 needs two long crossovers, so it cannot equal peptide 1.","3":"Peptides 3 and 4 have the same set of connections, so they are equal in length.","4":"Peptide 2 is the longest, not the second shortest."}}},{"id":107,"part":"C","unit":14,"blocks":[{"t":"p","h":"The magnetic field generated from an electromagnet is used in the transcranial magnetic stimulation (TMS) of the brain. The following statements suggest some features of TMS:"},{"t":"p","h":"A. The magnetic field generated in TMS induces an electrical field in the underlying brain area.<br>B. The electrical field in the brain area alters the membrane potential of the neurons in that locality causing them to depolarize synchronously, which in turn, may change the probability of the firing of neurons.<br>C. In cognitive neuroscience research, TMS may be used as a tool to induce a 'virtual lesion' in a selected region of the cerebral cortex.<br>D. TMS is safe and non-invasive but the neuronal activity of the stimulated area is disrupted for a long period of time."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"C and D only"},{"key":"4","text":"A only"}],"answer":"1","explanation":{"correct":"A is true: a brief, rapidly changing magnetic field passes the skull unattenuated and induces an electric field in the cortex (Faraday's law; Barker et al. 1985, <i>Lancet</i> 325:1106). B is true: the induced current depolarises axons and neurons synchronously, changing firing probability. C is true: a well-timed pulse transiently disrupts processing in the targeted region, creating a reversible \"virtual lesion\" (Pascual-Leone, Walsh &amp; Rothwell 2000, <i>Curr Opin Neurobiol</i> 10:232).","wrong":{"2":"D is false: the disruption is short-lived (milliseconds for single pulses, up to roughly an hour after repetitive protocols), not long-term.","3":"D is false.","4":"B and C are also true."}}},{"id":108,"part":"C","unit":10,"blocks":[{"t":"p","h":"The table below gives the avian community composition of three communities (X, Y, Z), where '1' indicates the presence of the species in the community and '0' indicates its absence."},{"t":"tbl","cls":"","rowHead":false,"head":[["Species","X","Y","Z"]],"rows":[["Red-vented bulbul","1","0","1"],["Purple sunbird","0","0","1"],["Common Babbler","0","1","1"],["Rufous treepie","1","1","1"],["Red-naped Ibis","1","1","0"],["Scarlet minivet","0","0","1"],["Spotted Owlet","0","1","0"]]},{"t":"p","h":"Select the option that lists the correct order of similarity between pairs of communities based on Sorensen's coefficient of similarity."}],"options":[{"key":"1","text":"(X,Y) &gt; (Y,Z) &gt; (X,Z)"},{"key":"2","text":"(X,Y) &gt; (X,Z) &gt; (Y,Z)"},{"key":"3","text":"(Y,Z) &gt; (X,Z) &gt; (X,Y)"},{"key":"4","text":"(X,Y) = (X,Z) = (Y,Z)"}],"answer":"2","explanation":{"correct":"Sørensen's index is QS = 2C/(A + B), where A and B are the species counts of the two communities and C the number shared. X has 3 species, Y has 4 and Z has 5. Every pair shares 2 species (X–Y: treepie and ibis; X–Z: bulbul and treepie; Y–Z: babbler and treepie). So QS(X,Y) = 4/7 = 0.57, QS(X,Z) = 4/8 = 0.50 and QS(Y,Z) = 4/9 = 0.44.","wrong":{"1":"(Y,Z) is the least similar pair, not the middle one.","3":"This is the reverse order.","4":"The shared count is equal, but the denominators differ."}}},{"id":109,"part":"C","unit":8,"blocks":[{"t":"p","h":"In <i>Drosophila melanogaster</i>, a cross was performed, and the resulting progeny are indicated below."},{"t":"tbl","cls":"","rowHead":false,"head":[["","Females","Males"]],"rows":[["P","Mutant: yellow body colour and sepia eye colour","Wild type: gray body colour and red eye colour"],["F<sub>1</sub>","Gray body colour and red eye colour","Yellow body colour and red eye colour"]]},{"t":"p","h":"The F<sub>1</sub> progeny were sib-mated and the F<sub>2</sub> progeny were analysed. The following statements were made based on the above crosses and analysis of the progeny:"},{"t":"p","h":"A. The mutation leading to sepia eye color is located on an autosome.<br>B. Yellow body is a dominant phenotype.<br>C. One fourth of the F<sub>2</sub> progeny will be males with yellow body color.<br>D. In this dihybrid cross, as the F<sub>2</sub> progeny do not show a 9:3:3:1 typical Mendelian ratio, the two genes can be assumed to be linked."},{"t":"p","h":"Which one of the following options correctly identifies each statement as True (T) or False (F) from A to D, respectively?"}],"options":[{"key":"1","text":"T, F, T, F"},{"key":"2","text":"F, T, T, F"},{"key":"3","text":"T, T, F, F"},{"key":"4","text":"F, F, T, T"}],"answer":"1","explanation":{"correct":"<b>Body colour</b> shows crisscross inheritance: mutant mothers give yellow sons and wild-type daughters, so <i>yellow</i> is X-linked recessive. <b>Eye colour</b> is wild type in both F₁ sexes, so <i>sepia</i> is autosomal recessive (A true). Yellow is not dominant, since F₁ daughters are gray (B false). In F₂ (X<sup>y</sup>X<sup>+</sup> × X<sup>y</sup>Y), half the sons are yellow, i.e. 1/2 × 1/2 = 1/4 of all progeny are yellow males (C true). The deviation from 9:3:3:1 is due to X-linkage of one gene, not to linkage between the two genes, which lie on different chromosomes (D false).","wrong":{"2":"A is true and B is false.","3":"C is true and B is false.","4":"A is true and D is false."}}},{"id":110,"part":"C","unit":6,"blocks":[{"t":"p","h":"A researcher placed plant cells in a hypertonic solution to cause the cells to shrink. The following statements are made regarding the plasmolysed cells."},{"t":"p","h":"A. Microtubules are lost in the plasmolysed cells.<br>B. Protoplasts are retracted in the plasmolysed cells.<br>C. Hechtian strands are lost during plasmolysis.<br>D. Patches of plasma membrane remain affixed to the wall."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B and C only"},{"key":"3","text":"A, C and D"},{"key":"4","text":"B and D"}],"answer":"4","explanation":{"correct":"In plasmolysis the protoplast pulls away from the wall (B). It stays tethered at wall–membrane attachment sites, where patches of plasma membrane remain stuck to the wall (D). These attachments are drawn out into <b>Hechtian strands</b>, membranous threads containing cytoskeletal elements, which <i>form</i> during plasmolysis and help the protoplast re-expand on deplasmolysis (Oparka 1994, <i>New Phytol</i> 126:571).","wrong":{"1":"A and C are false: the cortical cytoskeleton is retained and reorganised, and Hechtian strands appear rather than disappear.","2":"C is false, and D is omitted.","3":"A and C are false."}}},{"id":111,"part":"C","unit":5,"blocks":[{"t":"p","h":"Gradient formation of Fgf8 is governed by both diffusion from a localized source and removal of Fgf8 ligand through endocytosis. Both Rab5C and dynamin promote endocytosis. What would happen to the Fgf8 concentration gradient when Rab5C is overexpressed or dynamin is inhibited?"},{"t":"img","src":"data:image/webp;base64,","w":620,"h":365,"alt":"Four panels A to D of Fgf8 concentration against distance from source, each with a normal gradient, a dynamin-inhibition curve and a Rab5C-overexpression curve. A: both curves above normal. B: both below normal. C: dynamin inhibition above normal and shallower, Rab5C overexpression below normal and steeper. D: Rab5C overexpression above, dynamin inhibition below"}],"options":[{"key":"1","text":"A"},{"key":"2","text":"B"},{"key":"3","text":"C"},{"key":"4","text":"D"}],"answer":"3","explanation":{"correct":"Fgf8 forms a source–sink gradient: free diffusion from the source, with receptor-mediated endocytosis acting as the sink (Yu et al. 2009, <i>Nature</i> 461:533). Blocking endocytosis (dominant-negative dynamin) removes the sink, so Fgf8 spreads further: a higher, shallower gradient. Enhancing endocytosis (Rab5C overexpression) increases clearance, giving a lower, steeper, shorter-range gradient (Scholpp &amp; Brand 2004, <i>Curr Biol</i> 14:1834). Panel C shows exactly this.","wrong":{"1":"Rab5C overexpression cannot raise the gradient.","2":"Dynamin inhibition cannot lower the gradient.","4":"The effects of the two manipulations are reversed."}}},{"id":112,"part":"C","unit":7,"blocks":[{"t":"p","h":"Given below are some statements regarding growth hormone (GH) secretion in humans."},{"t":"p","h":"A. Fasting increases GH secretion.<br>B. REM sleep decreases GH secretion.<br>C. Cortisol increases GH secretion.<br>D. Hypoglycemia decreases GH secretion."},{"t":"p","h":"Which one of the options given below represents both correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"1","explanation":{"correct":"A is true: fasting (protein or energy deficit) stimulates GH. B is true: the largest GH pulse comes with slow-wave (stage N3) sleep, while REM sleep is associated with low GH output. GH thus follows a metabolic logic of mobilising fuel when glucose and fatty acids are low (Guyton &amp; Hall, ch. 76).","wrong":{"2":"C is false: glucocorticoids <i>inhibit</i> GH secretion (via somatostatin), and chronic excess stunts growth.","3":"C and D are false.","4":"D is false: hypoglycaemia is a potent GH stimulus (the basis of the insulin tolerance test)."}}},{"id":113,"part":"C","unit":10,"blocks":[{"t":"p","h":"A parasitoid infects a host to complete its life cycle. Which of the following life-history traits typically characterizes this parasitoid, assuming that only one parasitoid infects one host?"}],"options":[{"key":"1","text":"Intrinsic rate of population growth faster than hosts; Eventually fatal for the host"},{"key":"2","text":"Intrinsic rate of population growth slower than hosts; Immediately fatal for the host"},{"key":"3","text":"Intrinsic rate of population growth comparable to hosts; Eventually fatal for the host"},{"key":"4","text":"Intrinsic rate of population growth faster than hosts; Immediately fatal for the host"}],"answer":"3","explanation":{"correct":"A parasitoid's larva develops in or on a single host, which it consumes and kills only at the end of its development (eventually fatal). With one parasitoid per host, each parasitoid generation is tied to a host generation: one host yields one parasitoid. Generation time and potential population growth are therefore of the same order as the host's, as assumed in Nicholson–Bailey host–parasitoid dynamics (Godfray 1994, <i>Parasitoids</i>).","wrong":{"1":"With a one-to-one host–parasitoid relationship, the parasitoid cannot outgrow its host population.","2":"Death is not immediate; the host stays alive while the larva develops (unlike predation).","4":"Wrong on both growth rate and timing of death."}}},{"id":114,"part":"C","unit":7,"blocks":[{"t":"p","h":"When blood is forced into aorta from left ventricle during systole, a pressure wave is set up in aorta which is called pulse. Some features of the pulse are proposed in the following statements:"},{"t":"p","h":"A. The rate of travel of the pulse wave is lower than the velocity of blood flow in arteries.<br>B. The pulse wave moves slower with advancing age as the arteries become more rigid.<br>C. The pulse wave is strong when the stroke volume is large as in exercise.<br>D. The strength of the pulse depends on the magnitude of pulse pressure and not on the mean arterial pressure."},{"t":"p","h":"Which one of the following options represents the combination of correct statements?"}],"options":[{"key":"1","text":"A, B, C and D"},{"key":"2","text":"B, C and D only"},{"key":"3","text":"C and D only"},{"key":"4","text":"A only"}],"answer":"3","explanation":{"correct":"C is true: a larger stroke volume raises pulse pressure, so the pulse feels strong. D is true: the palpable pulse reflects pulse pressure (systolic − diastolic), not mean pressure.","wrong":{"1":"A and B are false: pulse-wave velocity (~4–5 m/s in the aorta, 7–10 m/s peripherally) far exceeds blood velocity (&lt;0.5 m/s), and stiffer arteries in old age conduct the wave <i>faster</i> (PWV is the clinical index of arterial stiffness).","2":"B is false.","4":"A is false."}}},{"id":115,"part":"C","unit":4,"blocks":[{"t":"p","h":"The statements below are made about some animal pathogens that may evade innate and inflammatory responses by the following mechanisms:"},{"t":"p","h":"A. The flagellin of Proteobacteria has a mutation that prevents it from being recognized by Toll-like receptors (TLRs).<br>B. The lipopolysaccharides of <i>Helicobacter</i> have mutations that prevent it from being recognized by TLRs.<br>C. <i>M. tuberculosis</i> escapes from the phagosome to the cytosol, thereby avoiding degradation by lysosomal enzymes.<br>D. Influenza virus produces Yop protein that inhibits inflammasome activity.<br>E. <i>S. typhi</i> encodes a protein that binds Type I IFNs and prevents them from binding to the IFN receptor."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"B and C"},{"key":"2","text":"A and C"},{"key":"3","text":"D and E"},{"key":"4","text":"A and B"}],"answer":"4","explanation":{"correct":"NTA's key is A and B. Both describe altered pathogen-associated molecular patterns that are poorly recognised by TLR5 (flagellin) and TLR4 (lipid A of LPS), as tabulated in standard immunology texts (Kuby Immunology, innate immunity chapter).","wrong":{"1":"C is the wrong organism: phagosome escape into the cytosol is the textbook strategy of <i>Listeria</i>; the classic <i>M. tuberculosis</i> strategy is blocking phagosome–lysosome fusion.","2":"C is false (see option 1).","3":"D and E name the wrong organisms: Yop proteins belong to <i>Yersinia</i>, and soluble interferon-binding decoys are made by poxviruses."}}},{"id":116,"part":"C","unit":3,"blocks":[{"t":"p","h":"A lac-lambda hybrid system is developed to study the λ-repressor protein, in which the λ <i>cI</i> gene is under the control of <i>E. coli lac</i> promoter and operator, and the <i>lacZ</i> gene is under the control of λ-P<sub>RM</sub> promoter and O<sub>R</sub> operator of λ-phage. Both the plasmids are introduced in <i>E. coli</i> and the concentrations of the proteins are determined upon the addition of IPTG."},{"t":"img","src":"data:image/webp;base64,","w":580,"h":515,"alt":"Two plasmids: lac promoter-operator driving lambda cI, and PRM with OR1-3 driving lacZ. Four graphs of protein against IPTG, with lambda repressor rising linearly in each. LacZ: A rises linearly; B falls linearly; C rises sigmoidally to a plateau; D stays high then falls"},{"t":"p","h":"Which graph correctly represents the expected results?"}],"options":[{"key":"1","text":"A"},{"key":"2","text":"B"},{"key":"3","text":"C"},{"key":"4","text":"D"}],"answer":"3","explanation":{"correct":"IPTG induces the <i>lac</i> promoter, so λ repressor rises steadily with IPTG. P<sub>RM</sub> is weak on its own and is <b>activated</b> by repressor bound cooperatively at O<sub>R</sub>1 and O<sub>R</sub>2, which contacts RNA polymerase. Because binding is cooperative, LacZ expression rises sigmoidally once repressor passes a threshold, then levels off (graph C) (Ptashne, <i>A Genetic Switch</i>).","wrong":{"1":"A straight-line LacZ response ignores cooperative activation.","2":"Repressor activates P<sub>RM</sub>; it does not shut it off.","4":"Same error as B."},"notes":["At very high repressor levels, occupancy of O<sub>R</sub>3 would eventually repress P<sub>RM</sub>; the graph covers the activation range."]}},{"id":117,"part":"C","unit":2,"blocks":[{"t":"p","h":"Actin dynamics in cells is dependent on several actin-binding proteins. Given below are actin-binding proteins in Column X and their typical function in Column Y."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Formin","I. Nucleates assembly to form a branched network"],["B. Arp2/3 complex","II. Stabilizes filament, modulates binding of other accessory proteins"],["C. Cofilin","III. Nucleates assembly and remains associated with the growing plus end"],["D. Tropomyosin","IV. Binds ADP-actin filaments, accelerates disassembly"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-(I) B-(II) C-(IV) D-(III)"},{"key":"2","text":"A-(III) B-(I) C-(IV) D-(II)"},{"key":"3","text":"A-(III) B-(II) C-(IV) D-(I)"},{"key":"4","text":"A-(II) B-(I) C-(IV) D-(III)"}],"answer":"2","explanation":{"correct":"Formins nucleate unbranched filaments and ride the growing barbed end (III). Arp2/3 nucleates branches at 70° on existing filaments (I). Cofilin binds ADP-actin, severs and speeds disassembly (IV). Tropomyosin lies along filaments, stabilising them and gating myosin and other binders (II).","wrong":{"1":"Swaps formin with Arp2/3 and puts tropomyosin as a nucleator.","3":"Makes Arp2/3 a stabiliser and tropomyosin a nucleator.","4":"Makes formin a stabiliser."}}},{"id":118,"part":"C","unit":14,"blocks":[{"t":"p","h":"A researcher needs to identify if Protein A is localized in the ER in a human cell line. The cell has an RFP-tagged protein that marks the ER in this cell. Following are the proposed experiments."},{"t":"p","h":"A. Express Protein A fused to GFP at the N-terminus in the cells, followed by microscopy to check for colocalization with RFP.<br>B. Express Protein A fused to GFP at the C-terminus in the cells, followed by microscopy to check for colocalization with RFP.<br>C. Immunofluorescence staining of A, followed by microscopy to check for colocalization with RFP.<br>D. Isolating the ER by differential centrifugation and checking for co-purification of Protein A with RFP."},{"t":"p","h":"Which one of the following options represents experiments that would most likely identify localization of Protein A in the ER?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"B, C and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and C only"}],"answer":"2","explanation":{"correct":"ER targeting depends on an N-terminal signal sequence recognised by SRP as it emerges from the ribosome. A C-terminal GFP tag leaves that signal free (B). Immunofluorescence detects the native, untagged protein (C). Subcellular fractionation (microsomes) checks whether Protein A co-sediments with the RFP-marked ER (D). So B, C and D are all valid.","wrong":{"1":"A is unreliable: an N-terminal GFP buries the signal sequence, so SRP cannot recognise it and the fusion stays in the cytosol, a false negative.","3":"Includes A (see option 1) and omits D.","4":"Omits D, a valid biochemical test of ER association."}}},{"id":119,"part":"C","unit":7,"blocks":[{"t":"p","h":"Urine volume is increased in osmotic diuresis which may be experimentally produced by the intravenous administration of mannitol that is filtered in the glomerulus but not reabsorbed in the renal tubule. The following statements suggest some of the physiological mechanisms of osmotic diuresis."},{"t":"p","h":"A. In the proximal tubule, water reabsorption falls due to presence of mannitol in tubular fluid and concentration of Na<sup>+</sup> is decreased in this fluid.<br>B. In the descending loop of Henle, reabsorption of water is increased as medullary hypertonicity is decreased in osmotic diuresis.<br>C. In the thin ascending loop of Henle, reabsorption of Na<sup>+</sup> is increased as the concentration gradient for Na<sup>+</sup> is decreased.<br>D. In the collecting duct, reabsorption of water is less because of decrease in osmotic gradient along the medullary pyramid in osmotic diuresis."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"4","explanation":{"correct":"Unreabsorbed mannitol holds water in the proximal tubule, so water reabsorption falls and tubular Na<sup>+</sup> is diluted; the steeper gradient favours Na<sup>+</sup> back-leak, so net Na<sup>+</sup> reabsorption falls too (A). The extra flow washes out the medullary interstitial gradient, so the collecting duct reabsorbs less water even with ADH present (D) (Ganong's <i>Review of Medical Physiology</i>; Guyton & Hall).","wrong":{"1":"B is wrong: a less hypertonic medulla <i>reduces</i> water exit from the descending limb.","2":"Both B and C are wrong; a smaller Na<sup>+</sup> gradient cannot increase passive Na<sup>+</sup> exit from the thin ascending limb.","3":"C is wrong (see option 2)."}}},{"id":120,"part":"C","unit":12,"blocks":[{"t":"p","h":"Given below are different types of bacterial growth curves."},{"t":"img","src":"data:image/webp;base64,","w":395,"h":300,"alt":"Four plots of number of cells against time. A: staircase of alternating rises and plateaus. B: smooth sigmoid curve. C: straight rising line. D: two sigmoid rises separated by a plateau"},{"t":"p","h":"Which one of the following options represents all correct matches between the growth curves and the type of culture?"}],"options":[{"key":"1","text":"A: Continuous; B: Asynchronous; C: Synchronous; D: Diauxic"},{"key":"2","text":"A: Synchronous; B: Continuous; C: Asynchronous; D: Diauxic"},{"key":"3","text":"A: Continuous; B: Asynchronous; C: Diauxic; D: Synchronous"},{"key":"4","text":"A: Synchronous; B: Asynchronous; C: Continuous; D: Diauxic"}],"answer":"4","explanation":{"correct":"A synchronous culture divides in step, so cell number doubles in bursts separated by plateaus (A, staircase). An ordinary batch culture is asynchronous and gives the smooth sigmoid lag–log–stationary curve (B). Diauxie gives two growth phases separated by a lag while the cells switch from the preferred sugar (glucose) to the second one (lactose) (D, Monod's classic observation). That leaves the straight line (C) for continuous culture, where fresh medium is supplied without limit.","wrong":{"1":"Swaps synchronous and continuous: the staircase is the hallmark of synchrony.","2":"The sigmoid curve is a batch (asynchronous) culture, not a continuous one.","3":"The two-step curve is diauxie, not synchrony."},"notes":["In a chemostat at steady state the cell <i>density</i> is constant and the total cells harvested rise linearly with time; NTA's key reads graph C in that sense."]}},{"id":121,"part":"C","unit":2,"blocks":[{"t":"p","h":"Protein X can be extracted from disrupted erythrocyte plasma membranes with high salt concentrations. Treatment of intact erythrocytes with protease followed by extraction led to intact protein X. Treatment of disrupted erythrocyte plasma membranes with protease followed by extraction led to fragmented protein X."},{"t":"p","h":"The following interpretations were made:<br>A. Protein X is a peripheral membrane protein<br>B. Protein X is an integral membrane protein<br>C. Protein X is on the extracellular matrix face of the plasma membrane<br>D. Protein X is on the cytosolic face of the plasma membrane"},{"t":"p","h":"Which one of the following options best represents the combination of all correct interpretations?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"A and D"},{"key":"3","text":"B and C"},{"key":"4","text":"B and D"}],"answer":"2","explanation":{"correct":"Release by high salt without detergent defines a peripheral protein held by ionic interactions (A). Protease cannot cross an intact membrane, so a protein that survives protease on intact cells but is cut once the membrane is opened must face the cytosol (D). Spectrin and ankyrin on the red-cell membrane behave this way (Alberts; Lehninger).","wrong":{"1":"An extracellular protein would be cleaved in intact cells.","3":"Integral proteins need detergent to be extracted, and the protein is not extracellular.","4":"Integral proteins need detergent to be extracted."}}},{"id":122,"part":"C","unit":7,"blocks":[{"t":"p","h":"The muscle spindles are the stretch receptors that initiate stretch reflex in skeletal muscles. The following statements are proposed to describe the structural and functional characteristics of the different components of a muscle spindle."},{"t":"p","h":"A. The specialized intrafusal fibers in muscle spindles have non-contractile polar ends and a contractile centre.<br>B. The intrafusal fibers do not contribute to the overall contractile force of the muscle.<br>C. The primary sensory ending in a muscle spindle is formed by group Ia afferent fibers.<br>D. The axons of α-motor neurons having a diameter of 12–20 µm innervate the muscle spindles as the motor nerve."},{"t":"p","h":"Which one of the following options represents the combination of correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"2","explanation":{"correct":"Intrafusal fibres are few and small and adjust spindle sensitivity rather than generate muscle force (B). The annulospiral primary ending around the central region is formed by large group Ia afferents (C) (Guyton & Hall, motor functions of the spinal cord).","wrong":{"1":"A is reversed: the polar ends contain the contractile myofibrils, and the central (equatorial) region is non-contractile and carries the sensory endings.","3":"D is wrong: spindles are innervated by small γ-motor neurons (about 3–6 µm); the 12–20 µm α-motor axons supply extrafusal fibres.","4":"Both A and D are wrong."}}},{"id":123,"part":"C","unit":5,"blocks":[{"t":"p","h":"Pollen tube growth in the transmission tract (TT) of the style and its attraction to the embryo sac are directed by chemical cues in plants, as discovered in Lily and Torenia. Which one of the following statements about the proteins/peptides secreted in the process is correct?"}],"options":[{"key":"1","text":"TT epidermis secretes cysteine-rich defensin-like peptides, whereas synergids (SY) secrete cysteine-rich adhesins."},{"key":"2","text":"TT epidermis secretes cysteine-rich adhesins, whereas SY secrete cysteine-rich defensin-like peptides."},{"key":"3","text":"TT epidermis secretes proline- and hydroxyproline-rich glycoproteins, whereas SY secrete cysteine-rich adhesin and chemocyanin."},{"key":"4","text":"TT epidermis secretes arabinogalactan proteins and chemocyanin, whereas the central cell of the embryo sac secretes cysteine-rich LURE peptides."}],"answer":"2","explanation":{"correct":"In lily, the transmitting-tract epidermis secretes SCA (stigma/stylar cysteine-rich adhesin), a small lipid-transfer-like protein that, with pectin, supports adhesion and guidance of the pollen tube. In <i>Torenia</i>, the synergid cells secrete LUREs, cysteine-rich defensin-like peptides that attract the tube to the micropyle (Taiz & Zeiger, <i>Plant Physiology and Development</i>, pollination chapter).","wrong":{"1":"Reverses the sources of the two peptide classes.","3":"Synergids secrete LUREs, not SCA or chemocyanin.","4":"LUREs come from the synergids, not the central cell; chemocyanin is a stigma/style protein."}}},{"id":124,"part":"C","unit":6,"blocks":[{"t":"p","h":"A researcher simultaneously inhibited the activities of Triose-Phosphate Translocator (TPT) and Xylulose 5-Phosphate Translocator (XPT) in a plant and made the following assumptions:"},{"t":"p","h":"A. Triose phosphate will be accumulated more in the chloroplast.<br>B. Triose phosphate will be accumulated more in the cytosol.<br>C. Xylulose 5-phosphate will be accumulated more in the chloroplast.<br>D. Xylulose 5-phosphate will be accumulated more in the cytosol."},{"t":"p","h":"Which one of the following combinations of the above assumptions is correct?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"A and D"},{"key":"3","text":"B and C"},{"key":"4","text":"B and D"}],"answer":"2","explanation":{"correct":"TPT exports triose phosphate made by the Calvin–Benson cycle in the light to the cytosol for sucrose synthesis, in exchange for P<sub>i</sub>. Blocking it traps triose phosphate in the stroma (A). XPT, a related phosphate translocator of the inner envelope, imports xylulose 5-phosphate from the cytosolic oxidative pentose phosphate pathway into the plastid. Blocking it leaves xylulose 5-phosphate in the cytosol (D) (Taiz & Zeiger; Buchanan, Gruissem & Jones).","wrong":{"1":"C is wrong: xylulose 5-phosphate normally moves into the plastid, so blocking XPT makes it pile up in the cytosol.","3":"B is wrong: triose phosphate normally leaves the chloroplast, so it accumulates inside.","4":"B is wrong (see option 3)."}}},{"id":125,"part":"C","unit":6,"blocks":[{"t":"p","h":"Following statements are made regarding methyl erythritol phosphate (MEP) and mevalonate pathways for plant terpenoid biosynthesis."},{"t":"p","h":"A. The MEP pathway occurs in plastids whereas mevalonate pathway occurs in cytosol.<br>B. The mevalonate pathway supplies most of the C<sub>5</sub> units of terpenoids for the biosynthesis of monoterpenes and diterpenes.<br>C. The MEP pathway supplies most of the C<sub>5</sub> units of terpenoids for the biosynthesis of sesquiterpenes.<br>D. Certain genes of the plant MEP pathway are believed to have been acquired from the cyanobacterial symbiont."},{"t":"p","h":"Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"C and D only"},{"key":"4","text":"A and D"}],"answer":"4","explanation":{"correct":"The MEP (non-mevalonate) pathway is plastidial and the mevalonate pathway is cytosolic/ER (A). The MEP pathway is the bacterial route to isopentenyl diphosphate, and plants are thought to have inherited genes for it with the cyanobacterial ancestor of the plastid (D). Plastidial IPP feeds hemiterpenes (isoprene), monoterpenes, diterpenes (gibberellins, phytol) and carotenoids; cytosolic IPP feeds sesquiterpenes, sterols and triterpenes (Taiz & Zeiger, secondary metabolites).","wrong":{"1":"B and C swap the pathways' products.","2":"B and C are wrong.","3":"C is wrong and A is omitted."},"notes":["The two pools exchange some IPP across the plastid envelope, so the split is 'most', not 'all'."]}},{"id":126,"part":"C","unit":10,"blocks":[{"t":"p","h":"A student studying tree species diversity uses a large number of sampling quadrats (each of 1-hectare area) to cover &gt;50% of the area of a 200-hectare tropical forest patch. Consider the statements in the options below:"},{"t":"p","h":"A. Species numbers increase with sampling area following a power-law relationship with exponent &gt;0 and &lt;1.<br>B. The log of species numbers increases linearly with the log of the sampling area.<br>C. Species numbers increase with sampling area following a power-law relationship with exponent &gt;1.<br>D. Species numbers increase linearly with the log of the sampling area."},{"t":"p","h":"Which combination of the statements above describes the expected pattern?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C only"},{"key":"3","text":"B and D"},{"key":"4","text":"A and D"}],"answer":"1","explanation":{"correct":"The species–area relationship is described by the Arrhenius power law S = cA<sup>z</sup>. Species accumulate ever more slowly, so 0 &lt; z &lt; 1 (typically about 0.1–0.4) (A). Taking logs gives log S = log c + z log A, a straight line on log–log axes (B) (Begon, Townsend & Harper, <i>Ecology</i>, islands and species–area chapter).","wrong":{"2":"z &gt; 1 would mean that species accumulate faster than area, which does not happen.","3":"Includes D.","4":"D is the alternative semi-log (Gleason) model, S = a + b log A. It is sometimes fitted to nested quadrat samples, but the expected pattern described in standard texts, and NTA's key, is the power law."}}},{"id":127,"part":"C","unit":14,"blocks":[{"t":"p","h":"The following statements describe a few basic features of the interferometric reflectance imaging sensor used as a biosensing platform:"},{"t":"p","h":"A. This biosensing platform is capable of high-throughput multiplexing of protein–protein, protein–DNA and DNA–DNA interactions.<br>B. The sensing surface is prepared by robotic spotting of biological probes that are immobilized on functionalised Si/SiO<sub>2</sub> substrate.<br>C. As biomass accumulates on the substrate surface, a change in the interferometric signature occurs and the change can be correlated to a quantifiable mass.<br>D. Using this technique, picometer changes in biomass may be detected."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"C and D only"},{"key":"4","text":"A only"}],"answer":"1","explanation":{"correct":"The interferometric reflectance imaging sensor (IRIS) is a label-free microarray reader. Probes are robotically spotted on a functionalised Si/SiO<sub>2</sub> layered chip (B). Binding adds optical thickness to the oxide layer and shifts the spectral reflectance (interference) signature, which converts to bound mass (C). Because hundreds of spots are imaged at once, it multiplexes protein and nucleic-acid interactions (A) (Özkumur <i>et al.</i>, <i>PNAS</i> 2008).","wrong":{"2":"Includes D and omits A.","3":"Includes D and omits A and B.","4":"B and C are also correct."},"notes":["D is excluded by the key: sensitivity is quoted as surface mass density (on the order of picograms per mm<sup>2</sup>), so 'picometer changes in biomass' mixes a length unit with a mass."]}},{"id":128,"part":"C","unit":10,"blocks":[{"t":"p","h":"A researcher uses taxon weighting and complementarity as criteria to prioritise communities for biodiversity conservation. The diagram below shows the distributions of five taxa (A to E) among four regions (R1–R4). Column W represents the weightage given to these five taxa based on their taxonomic uniqueness."},{"t":"img","src":"data:image/webp;base64,","w":470,"h":195,"alt":"Cladogram of taxa A to E beside a table. Weights W: A 1, B 1, C 2, D 3, E 4. R1 has A, B, C. R2 has B, C, D. R3 has B, D, E. R4 has B, C, E"},{"t":"p","h":"Select the option that lists the appropriate order of regions that should be prioritised (from highest to lowest) for conservation."}],"options":[{"key":"1","text":"R1 &gt; R3 &gt; R4 &gt; R2"},{"key":"2","text":"R2 &gt; R1 &gt; R3 &gt; R4"},{"key":"3","text":"R3 &gt; R1 &gt; R4 &gt; R2"},{"key":"4","text":"R4 &gt; R2 &gt; R1 &gt; R3"}],"answer":"3","explanation":{"correct":"Weighted scores: R1 = A+B+C = 1+1+2 = 4; R2 = B+C+D = 1+2+3 = 6; R3 = B+D+E = 1+3+4 = 8; R4 = B+C+E = 1+2+4 = 7. Pick R3 first. Complementarity then asks what each region adds that is not yet protected: R1 adds A and C (1+2 = 3); R2 and R4 add only C (2). So R1 is second. With R3 + R1 every taxon is protected, so the remaining two are ranked by their weighted scores: R4 (7) before R2 (6). Order: R3 &gt; R1 &gt; R4 &gt; R2 (Begon, Townsend & Harper; Vane-Wright, Humphries & Williams's taxic-weighting approach).","wrong":{"1":"Starts with R1, which has the lowest weighted score.","2":"Ignores the heavy weight of taxon E.","4":"Ignores complementarity: R1 is the only region holding taxon A."}}},{"id":129,"part":"C","unit":3,"blocks":[{"t":"p","h":"The following statements were made regarding the roles of histone modifications in transcriptional regulation."},{"t":"p","h":"A. Acetylation of histones is generally associated with transcriptional repression by making the chromatin more compact.<br>B. Methylation of histones can either activate or repress transcription depending on the specific residue modified.<br>C. Phosphorylation of histones occurs in response to DNA damage and can influence gene expression.<br>D. Histone modifications influence the recruitment of RNA polymerase complex but not transcription factors."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and D only"},{"key":"2","text":"B and C only"},{"key":"3","text":"B, C, and D"},{"key":"4","text":"A, B, and D"}],"answer":"2","explanation":{"correct":"Methylation's effect depends on the residue: H3K4me3 and H3K36me mark active genes; H3K9me3 and H3K27me3 mark silenced chromatin (B). Phosphorylation of H2A.X (γH2AX) is an early DNA-damage signal, and H3S10 phosphorylation accompanies immediate-early gene activation (C) (Alberts; Lodish).","wrong":{"1":"A is reversed: acetylation neutralises lysine charge, opens chromatin and is linked to activation. D is false: modified histones are read by bromodomain, chromodomain and PHD proteins, including transcription factors and coactivators.","3":"D is false (see option 1).","4":"A and D are false."}}},{"id":130,"part":"C","unit":9,"blocks":[{"t":"p","h":"The evolution of algal lineages is closely linked to endosymbiotic events. Which of the following statements best explains the origin and diversification of plastids in different algal groups?"}],"options":[{"key":"1","text":"Primary plastids originated from a eukaryotic host cell engulfing a red algal ancestor, followed by secondary endosymbiosis leading to the diversification of green and brown algal lineages."},{"key":"2","text":"Primary plastids evolved through the engulfment of a cyanobacterium by a eukaryotic host, while secondary and tertiary endosymbiosis involving red and green algae gave rise to plastids in diverse algal lineages such as diatoms and dinoflagellates."},{"key":"3","text":"All algal lineages acquired plastids through multiple independent primary endosymbiosis events, with cyanobacteria being engulfed by both red and green algal ancestors."},{"key":"4","text":"Secondary endosymbiosis was responsible for the origin of primary plastids in green algae, while tertiary endosymbiosis involving diatoms led to the evolution of plastids in red algae."}],"answer":"2","explanation":{"correct":"A single primary endosymbiosis of a cyanobacterium gave the double-membraned plastids of Archaeplastida (glaucophytes, red algae, green algae and land plants). Eukaryotes that engulfed red or green algae gained secondary plastids with three or four membranes: diatoms, brown algae and haptophytes (red-derived), euglenids and chlorarachniophytes (green-derived). Some dinoflagellates took up a diatom, haptophyte or cryptophyte, giving tertiary plastids (Raven, <i>Biology of Plants</i>; Lee, <i>Phycology</i>).","wrong":{"1":"The primary plastid came from a cyanobacterium, not from a red alga.","3":"Most algal groups (diatoms, brown algae, dinoflagellates) carry secondary or tertiary plastids, not primary ones.","4":"Green and red algal plastids are both primary; the direction of events is reversed."}}},{"id":131,"part":"C","unit":1,"blocks":[{"t":"p","h":"Given below are two columns depicting structural features (Column X) and the DNA/RNA conformation (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X: Structural features","Column Y: DNA/RNA conformation"]],"rows":[["A. Left-handed","i. A form"],["B. Number of base pairs per turn is 10","ii. B form"],["C. The base pairs are off-centered","iii. Z form"],["D. RNA double helix",""]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-(iii) B-(ii) C-(i) D-(i)"},{"key":"2","text":"A-(i) B-(iii) C-(ii) D-(i)"},{"key":"3","text":"A-(ii) B-(ii) C-(i) D-(iii)"},{"key":"4","text":"A-(iii) B-(i) C-(iii) D-(ii)"}],"answer":"1","explanation":{"correct":"Z-DNA is the left-handed form (A-iii). B-DNA has about 10 (10.5) bp per turn (B-ii). In A-form the base pairs are tilted and displaced about 4–5 Å off the helix axis, leaving a hollow core (C-i). The 2′-OH of ribose favours the C3′-endo sugar pucker, so double-stranded RNA adopts the A form (D-i) (Lehninger, nucleotides and nucleic acids; Saenger).","wrong":{"2":"A- and B-forms are right-handed; Z-DNA has 12 bp per turn.","3":"B-DNA is right-handed and RNA is not Z-form.","4":"A-form has 11 bp per turn, and RNA duplexes are A-form, not B-form."}}},{"id":132,"part":"C","unit":9,"blocks":[{"t":"p","h":"The statements given below describe an angiosperm flower."},{"t":"p","h":"A. A flower develops in the axils of bracts like axillary shoots.<br>B. The floral pedicel is the elongated node and the axis is condensed, like in a shoot.<br>C. Floral parts like calyx, corolla, androecium and gynoecium are modified leaves.<br>D. Floral buds may sometimes get modified into vegetative buds or bulbils."},{"t":"p","h":"Select the option with all correct statements that support the idea that a flower is a modified shoot."}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"A, B and D"},{"key":"3","text":"B, C and D"},{"key":"4","text":"A, C and D"}],"answer":"4","explanation":{"correct":"A flower arises in the axil of a bract just as a branch arises in a leaf axil (A). Floral organs are modified leaves (Goethe's idea, now supported by the ABC model: loss of A, B and C function turns every floral organ into a leaf-like structure) (C). Floral buds can revert to vegetative buds or bulbils, as in <i>Agave</i> and onion (D).","wrong":{"1":"B is wrong: the pedicel corresponds to an elongated <i>internode</i>; on the condensed thalamus it is the internodes that are suppressed.","2":"B is wrong (see option 1).","3":"B is wrong (see option 1)."}}},{"id":133,"part":"C","unit":8,"blocks":[{"t":"p","h":"The pedigree (Fig A) represents the inheritance of a monogenic disorder, caused by a defective enzyme encoded by a mutant allele. The functional and defective enzymes can be resolved by PAGE. The allozyme pattern observed in some of the individuals in the family is represented in Fig B. The frequency of the mutant allele in the population is 0.04."},{"t":"img","src":"data:image/webp;base64,","w":610,"h":220,"alt":"A: three-generation pedigree. I.1 and I.2 have children II.2 (married to II.1) and II.3 (married to II.4). II.1 and II.2 have III.1 (affected female), III.2 and III.3. B: gel lanes II.1, II.2, II.3, II.4, III.1, III.2, III.3. All lanes have an upper band. II.1, II.2, II.3, II.4 and III.2 also have a lower band; III.1 and III.3 have only the upper band"},{"t":"p","h":"Based on the above information, the following statements were made:"},{"t":"p","h":"A. The allele encoding the functional enzyme is haplo-sufficient.<br>B. The trait shows 100% penetrance.<br>C. The probability that a child born to individuals II.3 and II.4 will be homozygous for the gene is 1/4.<br>D. Both individuals I.1 and I.2 are necessarily heterozygous for the gene."},{"t":"p","h":"Which one of the following options correctly identifies each statement as True (T) or False (F) from A to D, respectively?"}],"options":[{"key":"1","text":"T, F, F, F"},{"key":"2","text":"T, F, T, F"},{"key":"3","text":"F, T, T, F"},{"key":"4","text":"F, F, F, T"}],"answer":"1","explanation":{"correct":"The affected girl III.1 shows a single band, so she is homozygous for the mutant allele, and the shared upper band is the mutant allozyme. All parents show two bands (heterozygous) yet are unaffected, so the disorder is recessive and one functional allele is enough: <b>A true</b>. III.3 has the same single-band (homozygous mutant) pattern but is unaffected, so penetrance is incomplete: <b>B false</b>. II.3 and II.4 are both heterozygous, so a child is homozygous (for either allele) with probability 1/4 + 1/4 = 1/2: <b>C false</b>. The grandparents' genotypes are not tested; two heterozygous children could also come from, say, a homozygous-mutant (non-penetrant) × homozygous-normal cross: <b>D false</b>.","wrong":{"2":"C would be true only for 'homozygous mutant'; the statement says homozygous for the gene, which includes both homozygotes.","3":"III.3 is a non-penetrant homozygote, so penetrance is not 100%.","4":"The parents' generation cannot be genotyped from these data."},"notes":["The population allele frequency (0.04) is a distractor here; it is not needed because every relevant parent is genotyped on the gel."]}},{"id":134,"part":"C","unit":4,"blocks":[{"t":"p","h":"The insulin receptor is a receptor tyrosine kinase that engages the PI3 kinase pathway to regulate a FOXO transcription factor. A student uses qRT-PCR to determine the expression of a direct FOXO target gene (GeneX) in a mammalian cell line under different conditions and makes the following observations."},{"t":"p","h":"A. Treating the cells with a PTEN inhibitor increases GeneX expression.<br>B. A cell line with an AKT (S308A) mutation has increased GeneX expression.<br>C. Change in GeneX expression due to a ligand-binding defective insulin receptor is partly reversed by a PTEN inhibitor.<br>D. Phosphorylation of FOXO by PDK1 creates a phosphoserine binding site for 14-3-3 protein, reducing GeneX expression."},{"t":"p","h":"Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"A and C only"},{"key":"3","text":"B and C only"},{"key":"4","text":"A, C and D"}],"answer":"3","explanation":{"correct":"Insulin → PI3K → PIP<sub>3</sub> → PDK1 phosphorylates AKT at its activation-loop residue 308 → AKT phosphorylates FOXO → 14-3-3 binds and holds FOXO in the cytosol → FOXO targets fall. An AKT mutant that cannot be phosphorylated at 308 is inactive, so FOXO stays nuclear and GeneX rises (B). A receptor that cannot bind insulin raises GeneX. A PTEN inhibitor lets basal PIP<sub>3</sub> build up and partly restores AKT signalling, partly reversing that rise (C) (Alberts; Lodish, insulin/PI3K signalling).","wrong":{"1":"A is wrong: blocking PTEN raises PIP<sub>3</sub> and AKT activity, which lowers FOXO target expression.","2":"A is wrong and B is omitted.","4":"A is wrong, and D names the wrong kinase: FOXO is phosphorylated by AKT, not PDK1."},"notes":["The AKT1 activation-loop residue is threonine 308; the question's 'S308A' is read as the non-phosphorylatable mutant at that site."]}},{"id":135,"part":"C","unit":13,"blocks":[{"t":"p","h":"Following statements are made with respect to the production of transgenic plants."},{"t":"p","h":"A. Auxin can be used as a negative selection marker in plant transgenesis as it can be lethal to germinating seedlings at higher concentrations.<br>B. <i>Agrobacterium</i> inserts T-DNA at random locations in the plant genome and thus, it cannot be targeted to a desired location.<br>C. The antibiotic kanamycin interferes with the cytoplasmic ribosomal protein synthesis machinery, thereby acting as a positive selection marker.<br>D. Gene transfer by biolistic/particle gun bombardment usually results in lower transgene copy number and less DNA rearrangement than <i>Agrobacterium</i>-mediated transformation."},{"t":"p","h":"Which one of the following options represents all INCORRECT statements?"}],"options":[{"key":"1","text":"A, C and D"},{"key":"2","text":"C and D only"},{"key":"3","text":"A and B"},{"key":"4","text":"B, C and D"}],"answer":"2","explanation":{"correct":"The question asks which statements are wrong. C is wrong: kanamycin inhibits the prokaryote-type 70S ribosomes of plastids and mitochondria, not the cytosolic 80S machinery; it is a positive marker because <i>nptII</i> detoxifies it. D is reversed: particle bombardment typically gives high-copy, rearranged insertions, whereas <i>Agrobacterium</i> tends to give clean, low-copy T-DNA inserts. A and B are correct statements, so they are excluded: high auxin concentrations are indeed lethal to germinating seedlings and can be used for negative (counter-)selection, and wild-type T-DNA integration is essentially random, so it cannot be aimed at a chosen locus without an added nuclease (Slater, Scott &amp; Fowler, <i>Plant Biotechnology</i>).","wrong":{"1":"A is a correct statement, so it cannot be part of the INCORRECT set.","3":"Both A and B are correct statements.","4":"B is correct, and A is left out of the set."},"notes":["The usual engineered counter-selection markers are <i>codA</i> (5-fluorocytosine) and <i>tms2</i> (naphthalene acetamide); NTA reads statement A in the broader sense that a high auxin dose kills germinating seedlings."]}},{"id":136,"part":"C","unit":2,"blocks":[{"t":"p","h":"Spindle assembly in animal cells requires nuclear envelope breakdown (NEBD). NEBD is a multistep process, which begins when Cdk1/cyclinB phosphorylates multiple components of the nuclear envelope. Given below are some components that are directly phosphorylated by Cdk1/cyclinB:"},{"t":"p","h":"A. Nuclear Pore Complexes<br>B. Nuclear lamina<br>C. Greatwall kinase<br>D. Histone H3"},{"t":"p","h":"Choose the option with correct Cdk1/cyclinB substrate/s that are directly associated with NEBD."}],"options":[{"key":"1","text":"B only"},{"key":"2","text":"A, B and D"},{"key":"3","text":"A and B only"},{"key":"4","text":"B, C and D"}],"answer":"3","explanation":{"correct":"At mitotic entry Cdk1/cyclin B phosphorylates nucleoporins, dismantling the nuclear pore complexes (A), and lamins A/C and B, depolymerising the lamina (B). These two events are the direct cause of nuclear envelope breakdown (Alberts, mitosis chapter).","wrong":{"1":"Pore-complex disassembly is an equally direct part of NEBD.","2":"Histone H3 phosphorylation belongs to chromosome condensation, not envelope breakdown (and H3S10 is mainly an Aurora B substrate).","4":"Greatwall kinase is a Cdk1 substrate, but it acts on the PP2A-B55 phosphatase branch, not on the envelope."}}},{"id":137,"part":"C","unit":10,"blocks":[{"t":"p","h":"Which one of the following is INCORRECT regarding Hill numbers (<i>q</i>), a family of diversity indices?"}],"options":[{"key":"1","text":"As q increases, the index puts increasing weight on the most common species in the assemblage, with the contribution of rare species gradually reducing in the summation."},{"key":"2","text":"As q increases, the index puts increasing weight on the rare species in the assemblage, with the contribution of common species gradually reducing in the summation."},{"key":"3","text":"As q increases, the diversity index decreases, unless all species are equally abundant."},{"key":"4","text":"Once q ≥ 5, Hill numbers rapidly converge to the inverse of the relative abundance of the most common species."}],"answer":"2","explanation":{"correct":"Hill numbers <sup>q</sup>D = (Σ p<sub>i</sub><sup>q</sup>)<sup>1/(1−q)</sup> raise each relative abundance to the power q, so larger q gives progressively more weight to abundant species and less to rare ones. Option 2 states the opposite, so it is the INCORRECT statement and the keyed answer (Hill 1973; Jost 2006; Chao's Hill-number framework).","wrong":{"1":"True: this is the defining behaviour of the family (q = 0 species richness, q = 1 exp(Shannon), q = 2 inverse Simpson).","3":"True: <sup>q</sup>D is a non-increasing function of q, and is flat only when all species are equally abundant.","4":"True: as q → ∞, <sup>q</sup>D → 1/p<sub>max</sub>, and convergence is quick in practice."}}},{"id":138,"part":"C","unit":7,"blocks":[{"t":"p","h":"The following statements are made about hematopoiesis in humans."},{"t":"p","h":"A. Bone marrow stem cells are not the source of osteoclast and mast cells.<br>B. Normally, three fourths of the cells in the marrow cavities mature to white blood cells and one fourth to red blood cells.<br>C. In adults, blood cells are not actively produced in the marrow cavities of all the bones.<br>D. Hematopoietic stem cells are derived from committed cells."},{"t":"p","h":"Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"2","explanation":{"correct":"The marrow is dominated by the granulocytic series: the myeloid:erythroid ratio in normal adult marrow is about 3:1, even though far more erythrocytes circulate, because red cells live ~120 days while granulocytes live hours to days (B). In adults active red marrow is confined to the axial skeleton and the proximal ends of long bones; elsewhere it is replaced by fatty yellow marrow (C) (Guyton &amp; Hall; Kuby Immunology).","wrong":{"1":"A is false: osteoclasts come from the monocyte–macrophage lineage and mast cells from a myeloid progenitor, both of marrow origin.","3":"D is false: commitment runs the other way — HSCs give rise to committed progenitors.","4":"Both A and D are false."}}},{"id":139,"part":"C","unit":1,"blocks":[{"t":"p","h":"Cells have both reversible and non-reversible post-translational modifications. The following statements were made regarding the reversibility of post-translational modifications."},{"t":"p","h":"A. Ubiquitination of proteins is reversible, but ADP-ribosylation of DNA is irreversible.<br>B. Ubiquitination of proteins is reversible, but myristoylation of proteins is irreversible.<br>C. Ubiquitination of proteins is irreversible, but ADP-ribosylation of DNA is reversible.<br>D. Both ADP-ribosylation of DNA and prenylation of proteins are reversible.<br>E. Both prenylation and myristoylation of proteins are irreversible."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A, D and E"},{"key":"3","text":"C and E"},{"key":"4","text":"B and E"}],"answer":"4","explanation":{"correct":"Ubiquitination is reversed by deubiquitinases (DUBs), a large family in every eukaryote. N-myristoylation forms a stable amide bond at an N-terminal glycine and is treated as irreversible, as is prenylation, a thioether link to a C-terminal cysteine. So B and E are both correct (Lehninger; Alberts).","wrong":{"1":"A is wrong: ADP-ribosylation is reversed by hydrolases such as PARG and ARH3.","2":"A and D contradict each other on ADP-ribosylation, and prenylation is not reversible.","3":"C is wrong: ubiquitination is reversible."}}},{"id":140,"part":"C","unit":6,"blocks":[{"t":"p","h":"RuBisCO enzyme catalyzes carboxylation or oxygenation of RuBP in five steps. Following are certain statements regarding the catalysis carried out by RuBisCO:"},{"t":"p","h":"A. The first step of catalysis is enolization of RuBP.<br>B. The carbon–carbon bond between C3 and C4 of RuBP is cleaved.<br>C. Carboxylase activity produces only one molecule of 3-phosphoglycerate.<br>D. Oxygenase activity produces one molecule of 3-phosphoglycerate and one molecule of 2-phosphoglycolate."},{"t":"p","h":"Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and D"},{"key":"2","text":"B, C and D"},{"key":"3","text":"B and C only"},{"key":"4","text":"A and D only"}],"answer":"4","explanation":{"correct":"Catalysis starts by abstracting the C3 proton to form the 2,3-enediolate of RuBP (A). CO<sub>2</sub> (or O<sub>2</sub>) adds at C2, and the six-carbon intermediate is hydrated and cleaved between C2 and C3 — in the oxygenase reaction that split gives one 3-phosphoglycerate (C3–C4–C5) and one 2-phosphoglycolate (C1–C2) (D). Carboxylation yields two molecules of 3-phosphoglycerate, so C is false, and the bond broken is C2–C3, not C3–C4, so B is false (Taiz &amp; Zeiger; Buchanan, Gruissem &amp; Jones).","wrong":{"1":"B is false: the scissile bond is C2–C3.","2":"B and C are both false.","3":"B and C are both false."}}},{"id":141,"part":"C","unit":10,"blocks":[{"t":"p","h":"The Marginal Value Theorem describes the behaviour of an animal foraging in a habitat where resources occur in patches. A major prediction of the theorem is how long an animal must stay in a patch to optimize the energy extracted, depending on its travel time to reach the patch, which is depicted in the figure below."},{"t":"img","src":"data:image/webp;base64,","w":445,"h":300,"alt":"Graph of cumulative energy extracted against time. A decelerating gain curve rises from the origin. A dashed tangent is drawn to it from a point Q on the negative part of the time axis, left of the origin; the tangent touches the curve above the point P on the positive time axis"},{"t":"p","h":"Based on this information, choose the option that correctly describes what both P and Q represent."}],"options":[{"key":"1","text":"P= Optimum cumulative energy extracted; Q= Optimum patch residence time"},{"key":"2","text":"P= Time taken to travel between patches; Q= Optimum cumulative energy extracted"},{"key":"3","text":"P= Optimum cumulative energy extracted; Q= Time taken to travel between patches"},{"key":"4","text":"P= Optimum patch residence time; Q= Time taken to travel between patches"}],"answer":"4","explanation":{"correct":"In Charnov's Marginal Value Theorem the gain curve within a patch decelerates as the patch is depleted. Travel time is plotted to the <b>left</b> of the origin, so Q is the travel time between patches. The line of maximum average intake is the tangent drawn from that travel-time point to the gain curve; the time coordinate of the tangent point, P, is the optimal patch residence time — the animal should leave when its marginal intake rate falls to the habitat-wide average (Begon, Townsend &amp; Harper, foraging chapter; Charnov 1976).","wrong":{"1":"Both labels are on the time axis, so neither can be an amount of energy; the roles are also swapped.","2":"Q lies on the time axis before the origin, which is travel time, not energy.","3":"P is a time on the x-axis, not a quantity of energy."},"notes":["The longer the travel time, the further left Q sits, the later the tangent touches the curve, and so the longer the animal should stay in each patch."]}},{"id":142,"part":"C","unit":5,"blocks":[{"t":"p","h":"Embryos of a species display conditional specification at 16-cell stage, and gastrulation begins at a later stage. In the 16-cell embryo, the prospective fate of vegetal blastomere is endoderm, while that of animal pole blastomere is ectoderm. In a 16-cell stage, a vegetal pole blastomere was grafted to the animal pole."},{"t":"p","h":"Which one of the following outcomes is true for the grafted cell?"}],"options":[{"key":"1","text":"It organizes the surrounding tissue to generate a secondary body axis."},{"key":"2","text":"It completely disrupts development."},{"key":"3","text":"It develops into endoderm."},{"key":"4","text":"It develops into ectoderm."}],"answer":"4","explanation":{"correct":"Conditional (regulative) specification means a blastomere's fate is set by signals from its neighbours, not by inherited cytoplasmic determinants, and remains labile until determination. Moved to the animal pole before gastrulation, the graft reads its new neighbourhood and develops according to its new position — as ectoderm (Gilbert, <i>Developmental Biology</i>, autonomous vs conditional specification).","wrong":{"1":"Organizer activity is a property of the dorsal blastopore lip at gastrulation, not of an ordinary vegetal blastomere at the 16-cell stage.","2":"Regulative embryos accommodate such grafts; that is the point of the experiment.","3":"Keeping the donor fate is the outcome in <i>autonomous</i> (mosaic) specification, which the question rules out."}}},{"id":143,"part":"C","unit":8,"blocks":[{"t":"p","h":"Six mutant yeast haploids (His1–6) requiring histidine supplementation for viability were fused in pair-wise combinations to form diploids. Requirement for histidine was tested for the diploids. The results are shown below where '+' indicates diploid combinations yielding histidine prototrophs."},{"t":"tbl","cls":"","rowHead":false,"head":[["","His1","His2","His3","His4","His5","His6"]],"rows":[["His1","–","+","–","+","+","–"],["His2","+","–","+","–","–","+"],["His3","–","+","–","+","+","–"],["His4","+","–","+","–","–","+"],["His5","+","–","+","–","–","+"],["His6","–","+","–","+","+","–"]]},{"t":"p","h":"How many different histidine biosynthesis genes are represented among the six mutants?"}],"options":[{"key":"1","text":"One"},{"key":"2","text":"Two"},{"key":"3","text":"Three"},{"key":"4","text":"Four"}],"answer":"2","explanation":{"correct":"In a complementation test, two recessive mutations in <b>different</b> genes complement (prototroph, '+'), while two in the same gene do not ('–'). His1 fails to complement His3 and His6 but complements His2, His4 and His5. Grouping all mutants that fail to complement one another gives exactly two complementation groups — {His1, His3, His6} and {His2, His4, His5} — so two genes are represented (Griffiths, <i>Introduction to Genetic Analysis</i>).","wrong":{"1":"One gene would make every diploid a histidine auxotroph ('–' throughout).","3":"A third group would need a mutant that fails to complement some strain outside these two sets.","4":"Four groups would show far more '+' entries than the table contains."}}},{"id":144,"part":"C","unit":9,"blocks":[{"t":"p","h":"Synonymous mutations (solid black circle) and non-synonymous mutations (different symbols) are plotted on two hypothetical phylogenies (A and B) given below."},{"t":"img","src":"data:image/webp;base64,","w":490,"h":265,"alt":"Two phylogenetic trees. Tree A carries mostly solid black circles on its branches with a single open square. Tree B carries a variety of different symbols: filled square, filled triangle, open triangle, open square and open circle"},{"t":"p","h":"The phylogenies above may represent the following types of selection — positive, negative or neutral. Which one of the options given below gives the correct combination of the types of selection observed in phylogenies A and B?"}],"options":[{"key":"1","text":"A shows negative selection, B shows positive selection."},{"key":"2","text":"A shows positive selection, B shows negative selection."},{"key":"3","text":"A shows neutral selection, B shows positive selection."},{"key":"4","text":"A shows positive selection, B shows neutral selection."}],"answer":"1","explanation":{"correct":"Synonymous changes do not alter the protein and are nearly neutral, so they accumulate freely. Tree A is dominated by synonymous changes with almost no amino-acid replacements: replacements are being removed, i.e. purifying (negative) selection, d<sub>N</sub>/d<sub>S</sub> &lt; 1. Tree B carries many different non-synonymous changes spread over the branches, the signature of repeated adaptive replacement, i.e. positive (diversifying) selection, d<sub>N</sub>/d<sub>S</sub> &gt; 1 (Futuyma, <i>Evolution</i>; the McDonald–Kreitman and d<sub>N</sub>/d<sub>S</sub> logic).","wrong":{"2":"Reverses the two trees.","3":"Strict neutrality would show synonymous and non-synonymous changes in roughly the proportion expected by chance, not the near-absence of replacements seen in A.","4":"Reverses A, and B is not neutral."}}},{"id":145,"part":"C","unit":5,"blocks":[{"t":"p","h":"Given below are the outcomes of transplantation experiments."},{"t":"img","src":"data:image/webp;base64,","w":505,"h":490,"alt":"Four transplantation experiments with outcomes. A: Xenopus, dorsal region grafted to the ventral side of a host, outcome formation of two embryonic axes with the same anterior-posterior polarity. B: newt, anterior-most portion of the archenteron roof including head mesoderm placed in the blastocoel, outcome formation of ectopic nose, eyes, balancers and otic vesicles. C: newt, older dorsal lip placed in the blastocoel, outcome formation of a secondary tail. D: zebrafish, dorsal-most region of the embryonic shield grafted to the ventral side of a host, outcome formation of two embryonic axes with opposite anterior-posterior polarity"},{"t":"p","h":"Which one of the following options correctly depicts the outcome of the transplantation experiments?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"B and D"}],"answer":"1","explanation":{"correct":"A is the Spemann–Mangold organizer graft: a dorsal lip grafted to the ventral side of a <i>Xenopus</i> host induces a conjoined secondary axis that runs with the same anterior–posterior polarity as the host's own. C is Spemann's heterochronic result: an <b>older</b> (late-gastrula) dorsal lip has already become posterior mesoderm, so it induces a secondary tail rather than a head. D is wrong: the zebrafish embryonic shield is the fish organizer and induces a secondary axis of the <i>same</i> polarity, not an opposite one. Since A is right and D is wrong, the answer is A and C (Gilbert, <i>Developmental Biology</i>, the organizer).","wrong":{"2":"Pairs C with B instead of A, but A is a correctly depicted outcome.","3":"Includes D, whose stated reversal of polarity is wrong.","4":"Includes D and omits A."},"notes":["B — Mangold's graft of anterior archenteron roof (head mesoderm) inducing ectopic head structures — is also a textbook result, so B could be argued as correctly depicted. It does not change the answer: every option pairs two statements, and only option 1 keeps the correct A while excluding the wrong D."]}}];
